function enhanceAccessibility(root=document){
 const q=(sel)=>Array.from(root.querySelectorAll?.(sel)||[]);
 q('.navBtn').forEach(b=>{if(b.classList.contains('active'))b.setAttribute('aria-current','page');else b.removeAttribute('aria-current')});
 q('.confBtn,[data-ltab],[data-leader],[data-rot-mode],[data-board-action],[data-draft-target],.boxTabs button,.speedRow button').forEach(b=>b.setAttribute('aria-pressed',b.classList.contains('active')?'true':'false'));
 q('.close').forEach(b=>{if(!b.getAttribute('aria-label'))b.setAttribute('aria-label','Close dialog')});
 q('button').forEach(b=>{if(!b.getAttribute('type'))b.setAttribute('type','button')});
 q('img').forEach(i=>{if(!i.hasAttribute('alt'))i.setAttribute('alt','')});
 const sheet=document.getElementById?.('sheet');if(sheet){sheet.setAttribute('role','dialog');sheet.setAttribute('aria-modal','true');sheet.setAttribute('aria-label','Player and transaction details')}
}
