function closeSheet(){const t=team(userTeam);$('#sheet').classList.remove('open');document.body.style.overflow='';setColors(t)}
function toast(text){let el=document.getElementById('toast');if(!el){el=document.createElement('div');el.id='toast';el.className='toast';el.setAttribute('role','status');el.setAttribute('aria-live','polite');el.setAttribute('aria-atomic','true');document.body.appendChild(el)}el.textContent=text;el.classList.add('show');setTimeout(()=>el.classList.remove('show'),1800)}


/* v0.12 — CONTRACTS + CBA ENGINE */
const CBA=window.NBA_COURTSIDE_CBA;
function birdLevelFromClock(v){return (+v||0)>=3?'bird':(+v||0)>=2?'early_bird':'non_bird'}
function birdClockSeed(p){return Math.max(1,Math.min(3,+p?.bird_rights_2027_seed_years||1))}
function birdLevelFor(p){return birdLevelFromClock(state.birdClock?.[p.id]??birdClockSeed(p))}
function ensureCbaState(){
 state.version=SAVE_SCHEMA;state.playoffStats=state.playoffStats||{};state.playoffGameLogs=state.playoffGameLogs||{};state.postseasonResults=state.postseasonResults||{};state.contractOverrides=state.contractOverrides||{};state.freeAgentRights=state.freeAgentRights||{};state.exceptionUsage=state.exceptionUsage||{};state.hardCaps=state.hardCaps||{};state.teamTenure=state.teamTenure||{};state.birdClock=state.birdClock||{};state.contractHistory=state.contractHistory||[];state.optionHistory=state.optionHistory||[];state.exceptionHistory=state.exceptionHistory||{};state.deadCapLedger=state.deadCapLedger||{};state.apronHistory=state.apronHistory||{};
 for(const p of players){const a=currentTeam(p);if(a&&state.teamTenure[p.id]==null)state.teamTenure[p.id]=Math.min(3,Math.max(1,(p.contract?.years||[]).length||1));if(a&&state.birdClock[p.id]==null){const extra=Math.max(0,(state.seasonYear||2026)-2027)+(state.seasonYear>=2027&&state.seasonStarted?1:0);state.birdClock[p.id]=Math.min(3,birdClockSeed(p)+extra)}}
}
ensureCbaState();
function contractYears(p){return state.contractOverrides?.[p.id]?.years||p?.contract?.years||[]}
function contractYear(p,year=state.seasonYear){return contractYears(p).find(y=>y.season_start===year)}
function salaryBase(p){return contractYear(p)?.amount ?? p?.contract?.cap_hold ?? 0}
function salaryOf(p){if(state.contractOverrides?.[p.id])return salaryBase(p);return Object.prototype.hasOwnProperty.call(state.salaryOverrides,p.id)?state.salaryOverrides[p.id]:salaryBase(p)}
function rightsFor(p,a){
 const r=state.freeAgentRights?.[p.id];
 if(r&&r.team===a)return r.renounced?null:r;
 if(p.roster_status==='restricted_free_agent_unsigned'&&(p.rights_team||p.team)===a){
   const overridden=state.freeAgentRights?.[p.id];
   if(overridden?.renounced)return null;
   return {team:a,type:'RFA',level:p.bird_rights_initial_2026_level||'bird',last_salary:p.contract?.qualifying_offer||p.contract?.cap_hold||salaryOf(p),cap_hold:p.contract?.cap_hold||p.contract?.qualifying_offer||0,qualifying_offer:p.contract?.qualifying_offer||0,renounced:false};
 }
 return null
}

function rightsHold(a){return players.filter(p=>currentTeam(p)==null).reduce((sum,p)=>{const r=rightsFor(p,a);return sum+(r?.cap_hold||0)},0)}

function deadCapFor(a,year=state.seasonYear){return (state.deadCap?.[a]||0)+(state.deadCapLedger?.[a]?.[year]||0)}
function incompleteRosterCharge(a){
 if(state.seasonStarted||!['offseason','draft','free_agency'].includes(state.phase))return 0;
 const underContract=teamPlayers(a).filter(p=>currentStatus(p)!=='retired'&&!isTwoWay(p)&&currentStatus(p)!=='waivers').length;
 const empty=Math.max(0,12-underContract);
 return empty*CBA.modeledMinimum(CAP.salary_cap,{age:19,years_service:0});
}
function capHit(a){return teamPlayers(a).reduce((s,p)=>s+salaryOf(p),0)+deadCapFor(a)+(state.otherCap[a]||0)+rightsHold(a)+incompleteRosterCharge(a)}

function capStatus(v){return v>CAP.second_apron?'SECOND APRON':v>CAP.first_apron?'FIRST APRON':v>CAP.luxury_tax?'LUXURY TAX':v>CAP.salary_cap?'OVER CAP':'CAP SPACE'}
function cbaAmounts(){return CBA.exceptionAmounts(CAP.salary_cap)}
function usageFor(a){
 state.exceptionUsage[a]=state.exceptionUsage[a]||{};
 const prev=state.exceptionHistory?.[state.seasonYear-1]?.[a];
 if(state.exceptionUsage[a].bae_last_year==null)state.exceptionUsage[a].bae_last_year=!!prev?.bae;
 return state.exceptionUsage[a]
}

function hardCapFor(a){return state.hardCaps?.[a]||null}
function setHardCap(a,amount,reason){if(!amount)return;const cur=state.hardCaps[a];if(!cur||amount<cur.amount)state.hardCaps[a]={amount,reason,season:state.seasonYear}}
function availableExceptions(a){const ch=capHit(a),e=cbaAmounts(),u=usageFor(a),room=Math.max(0,CAP.salary_cap-ch),hard=hardCapFor(a);return {room,non_taxpayer_mle:Math.max(0,e.non_taxpayer_mle-(u.nt_mle||0)),taxpayer_mle:Math.max(0,e.taxpayer_mle-(u.tax_mle||0)),room_mle:Math.max(0,e.room_mle-(u.room_mle||0)),biannual:Math.max(0,e.biannual-(u.bae||0)),minimum:'AVAILABLE',hard}}
function maxSalaryFor(p){const prior=faRightsRecord?.(p)?.last_salary||salaryOf(p)||0;return CBA.maxSalary(CAP.salary_cap,p,prior)}
function marketAsk(p){if(p.roster_status==='restricted_free_agent_unsigned')return p.contract?.qualifying_offer||p.contract?.cap_hold||salaryOf(p);const o=overall(p),base=(o>=92?42:o>=88?34:o>=84?25:o>=80?17:o>=77?11:o>=74?7:o>=70?4:2.5)*1e6;const age=p.age>=36?.72:p.age>=33?.86:p.age<=23?1.08:1;return Math.min(maxSalaryFor(p),Math.round(base*age/1000)*1000)}
function capRoomAfter(a,delta){return capHit(a)+delta}
function signingRoutesFor(p,a,amount){
 const own=rightsFor(p,a),hc=hardCapFor(a);
 return CBA.signingRoutes({teamSalary:capHit(a),cap:CAP.salary_cap,tax:CAP.luxury_tax,firstApron:CAP.first_apron,secondApron:CAP.second_apron,amount,usage:usageFor(a),ownRights:own,player:p,existingHardCap:hc?.amount||null})
}

function routeTermLegal(route,years,lastOption='guaranteed'){if(!route)return false;const optionYears=lastOption==='guaranteed'?0:1;return years>=(route.minYears||1)&&years<=(route.years||4)&&(route.id!=='early_bird'||years-optionYears>=2)}
function chooseSigningRoute(p,a,amount,years=null,lastOption='guaranteed'){const rs=signingRoutesFor(p,a,amount);return (years==null?rs:rs.filter(r=>routeTermLegal(r,years,lastOption)))[0]||null}
function optionLabel(o){return o==='player_option'?'PLAYER OPTION':o==='team_option'?'TEAM OPTION':o==='early_termination'?'ETO':'GUARANTEED'}
function installContract(p,a,{years,firstSalary,lastOption='guaranteed',route='cap_room',raise=null}){
 const own=rightsFor(p,a),bird=route==='bird'||route==='early_bird',rpct=raise??(bird ? .08 : .05),rows=CBA.buildContract({seasonYear:state.seasonYear,years,firstSalary,raise:rpct,lastOption,source:route});
 state.contractOverrides[p.id]={years:rows,expiry:'UFA',signed:state.date,route,team:a};
 state.salaryOverrides[p.id]=firstSalary;state.assignments[p.id]=a;state.statusOverrides[p.id]='active';
 state.teamTenure[p.id]=own?Math.max(1,state.teamTenure[p.id]||1):1;
 state.birdClock[p.id]=own?Math.max(0,state.birdClock[p.id]??birdClockSeed(p)):(state.seasonYear===2026&&!state.seasonStarted?1:0);
 delete state.freeAgentRights[p.id];
 const u=usageFor(a);
 if(route==='nt_mle'){u.nt_mle=(u.nt_mle||0)+firstSalary;u.first_apron_transaction=true;setHardCap(a,CAP.first_apron,'NON-TAXPAYER MLE')}
 if(route==='tax_mle'){u.tax_mle=(u.tax_mle||0)+firstSalary;setHardCap(a,CAP.second_apron,'TAXPAYER MLE')}
 if(route==='room_mle')u.room_mle=(u.room_mle||0)+firstSalary;
 if(route==='bae'){u.bae=(u.bae||0)+firstSalary;u.first_apron_transaction=true;setHardCap(a,CAP.first_apron,'BI-ANNUAL EXCEPTION')}
 state.contractHistory.unshift({player_id:p.id,team:a,date:state.date,years,firstSalary,route,lastOption});resetMoraleAfterMove(p,a)
}

function contractAccepts(p,years,firstSalary,a){const ask=marketAsk(p),dir=teamDirection(a),roleBoost=['contender','playoff_push'].includes(dir.id)?.04:0,security=years>=3?.05:years===2?.02:0,m=state.playerMorale?.[p.id],loyal=(rightsFor(p,a)?0.04:0);const need=ask*(.94-roleBoost-security-loyal);return firstSalary>=need||(m?.score<40&&currentTeam(p)===a)}
function contractOfferOptions(p,a=userTeam){
 const ask=marketAsk(p),own=rightsFor(p,a),externalRfa=currentTeam(p)==null&&faRightsRecord(p)?.type==='RFA'&&!own,maxY=CBA.maxYears({bird:own?.level==='bird'}),min=CBA.modeledMinimum(CAP.salary_cap,p),opts=[];
 if(own?.type==='RFA'&&own.qualifying_offer)opts.push({label:'QUALIFYING OFFER',years:1,salary:own.qualifying_offer,lastOption:'guaranteed',qualifying:true});
 opts.push({label:'2 YEARS · PREMIUM',years:2,salary:Math.min(maxSalaryFor(p),Math.round(ask*1.02/1000)*1000),lastOption:'guaranteed'},{label:'3 YEARS · MARKET',years:Math.min(3,maxY),salary:ask,lastOption:'guaranteed'},{label:'4 YEARS · SECURITY',years:Math.min(4,maxY),salary:Math.round(ask*.98/1000)*1000,lastOption:'guaranteed'},{label:'PLAYER OPTION',years:Math.min(4,maxY),salary:Math.round(ask*.97/1000)*1000,lastOption:'player_option'},{label:'TEAM OPTION',years:Math.min(3,maxY),salary:Math.min(maxSalaryFor(p),Math.round(ask*1.04/1000)*1000),lastOption:'team_option'},{label:'AGGRESSIVE BID',years:Math.min(4,maxY),salary:Math.min(maxSalaryFor(p),Math.round(ask*1.08/1000)*1000),lastOption:'guaranteed'});
 if(!externalRfa)opts.push({label:'MINIMUM',years:1,salary:min,lastOption:'guaranteed'});
 if(own?.level==='bird'&&maxY===5)opts.splice(4,0,{label:'5 YEARS · BIRD',years:5,salary:Math.round(ask*.97/1000)*1000,lastOption:'guaranteed'});
 return opts.filter((x,i,ar)=>x.years>=1&&(!externalRfa||x.years>1)&&ar.findIndex(y=>y.label===x.label)===i)
}

function submitContractOfferImmediate(p,years,firstSalary,lastOption='guaranteed'){
 if(signedCount(userTeam)>=15&&currentTeam(p)!==userTeam){toast('ROSTER FULL');return false}
 const own=rightsFor(p,userTeam),rfa=rightsFor(p,p.rights_team||p.team),isExternalRfa=currentTeam(p)==null&&rfa?.type==='RFA'&&rfa.team!==userTeam,isOwnQO=own?.type==='RFA'&&years===1&&Math.abs(firstSalary-(own.qualifying_offer||0))<2;
 if(isExternalRfa&&years<=1){toast('OFFER SHEET MUST BE MULTI-YEAR');return false}
 let route=isOwnQO?{id:own.level||'bird',label:'QUALIFYING OFFER',max:firstSalary,years:1,minYears:1,hardCap:null}:chooseSigningRoute(p,userTeam,firstSalary,years,lastOption);
 if(isExternalRfa){const room=Math.max(0,CAP.salary_cap-capHit(userTeam));if(firstSalary>room+1){toast('RFA OFFER NEEDS CAP ROOM');return false}route={id:'cap_room',label:'CAP SPACE',max:room,years:4,minYears:1,hardCap:null}}
 if(!route){if(signingRoutesFor(p,userTeam,firstSalary).length)toast('TERM NOT LEGAL');else toast('NO LEGAL CAP ROUTE');return false}
 if(isExternalRfa){
   const prior=rfa.team,priorRoute=chooseSigningRoute(p,prior,firstSalary,years,lastOption),matchValue=playerTradeValue(p,prior),match=!!priorRoute&&(matchValue>42||overall(p)>=78||firstSalary<=marketAsk(p)*1.02);
   if(match){installContract(p,prior,{years,firstSalary,lastOption,route:priorRoute.id});addTransaction('RFA MATCH',`${prior} matched ${userTeam}'s ${years}-year offer sheet for ${p.name}.`);toast(`${prior} MATCHED`);persist();closeSheet();renderView();return false}
   installContract(p,userTeam,{years,firstSalary,lastOption,route:'cap_room'});addTransaction('OFFER SHEET',`${userTeam} signed ${p.name} to a ${years}-year offer sheet; ${prior} declined to match.`);toast('OFFER SHEET WON');persist();closeSheet();renderView();return true
 }
 if(own?.type==='RFA'&&years===1&&Math.abs(firstSalary-(own.qualifying_offer||0))<2){installContract(p,userTeam,{years:1,firstSalary,lastOption:'guaranteed',route:own.level||'bird',raise:0});state.contractOverrides[p.id].expiry='UFA';addTransaction('QUALIFYING OFFER',`${p.name} accepted ${userTeam}'s one-year qualifying offer at ${money(firstSalary)}.`);persist();closeSheet();renderView();toast('QUALIFYING OFFER ACCEPTED');return true}
 if(!contractAccepts(p,years,firstSalary,userTeam)){toast('PLAYER DECLINED');return false}
 installContract(p,userTeam,{years,firstSalary,lastOption,route:route.id});addTransaction('SIGNED',`${userTeam} signed ${p.name} for ${years} year${years>1?'s':''}, ${money(firstSalary)} in Year 1 via ${route.label}.`);persist();closeSheet();renderView();toast(`${p.name.toUpperCase()} SIGNED`);return true
}

function renounceRights(p){
 let r=state.freeAgentRights?.[p.id];
 if(!r&&p.roster_status==='restricted_free_agent_unsigned'&&(p.rights_team||p.team)===userTeam){r=state.freeAgentRights[p.id]={team:userTeam,type:'RFA',level:'bird',last_salary:p.contract?.qualifying_offer||0,cap_hold:p.contract?.cap_hold||0,qualifying_offer:p.contract?.qualifying_offer||0,renounced:false}}
 if(!r||r.team!==userTeam)return;
 r.renounced=true;state.birdClock[p.id]=0;addTransaction('RENOUNCED',`${userTeam} renounced rights to ${p.name}; the cap hold was removed.`);persist();closeSheet();renderView();toast('RIGHTS RENOUNCED')
}

function extensionEligible(p){if(currentTeam(p)!==userTeam)return false;const ys=contractYears(p).filter(y=>y.season_start>=state.seasonYear).sort((a,b)=>a.season_start-b.season_start);return ys.length>=1&&ys.length<=2&&state.phase!=='draft'}
