function scoutingView(){const dx=ensureDraftExperience(),board=userBoardAvailable().slice(0,30),targets=dx.targets.map(id=>byId.get(id)).filter(p=>p&&currentStatus(p)==='draft_prospect');return `${hero()}<section class="scoutingHero"><span>${state.seasonYear} PRE-DRAFT</span><h2>BUILD<br>YOUR BOARD.</h2><div class="scoutPoints"><b>${dx.scoutingPoints}</b><span>SCOUTING POINTS</span></div></section><div class="offseasonSteps"><div class="done">✓<span>LOTTERY</span></div><div class="active">2<span>SCOUTING</span></div><div>3<span>DRAFT</span></div><div>4<span>FREE AGENCY</span></div><div>5<span>CAMP</span></div></div>${targets.length?`<div class="sectionHead"><h2>Your Targets</h2><span>${targets.length}/8</span></div><div class="targetRail">${targets.map(p=>`<button data-prospect-open="${p.id}"><div>${initials(p.name)}</div><strong>${p.name}</strong><span>${p.positions.join('/')}</span></button>`).join('')}</div>`:''}<div class="sectionHead"><h2>Your Draft Board</h2><span>DRAG-FREE REORDER</span></div><div class="notice"><strong>Scouting uncertainty is real.</strong> Early reports show broad ranges. Spend points or hold a private workout to narrow the current-ability estimate and reveal strengths, concerns and archetype.</div><div class="prospectBoard">${board.map((p,i)=>prospectBoardCard(p,i)).join('')}</div><button class="primaryAction" id="startDraftNight">START ${state.seasonYear} NBA DRAFT</button>${offseasonSummaryView()}`}
function draftPickValue(pick){return 1000*Math.exp(-.055*Math.max(0,pick-1))}
function draftFutureAssetValue(a){const years=Math.max(1,a.year-state.seasonYear);return (a.round===1?260:72)*Math.pow(.88,years-1)}
function nextOwnedDraftPick(owner,after=state.draft.pickIndex+1){for(let i=after;i<state.draft.order.length;i++)if(state.draft.order[i]===owner)return i+1;return null}
function generateShopPickOffers(){const dx=ensureDraftExperience(),pick=state.draft.pickIndex+1;if(currentDraftTeam()!==userTeam)return[];const curVal=draftPickValue(pick),offers=[],seen=new Set();for(let i=pick;i<Math.min(60,pick+18);i++){const tm=state.draft.order[i];if(!tm||tm===userTeam||seen.has(tm))continue;seen.add(tm);const later=i+1,laterVal=draftPickValue(later),assets=(state.draftAssets||[]).filter(a=>a.owner===tm&&a.year>state.seasonYear&&a.tradeable!==false).sort((a,b)=>a.year-b.year||a.round-b.round);const add=[];let value=laterVal;for(const a of assets){if(value>=curVal*.94)break;if(a.round===2||curVal-value>150){add.push(a.id);value+=draftFutureAssetValue(a)}if(add.length>=2)break}if(value>=curVal*.88)offers.push({from:tm,currentPick:pick,laterPick:later,assets:add,value:+value.toFixed(1)})}dx.tradeOffers=offers.sort((a,b)=>b.value-a.value).slice(0,3);persist();renderView();return dx.tradeOffers}
function acceptShopPickOffer(idx){const dx=ensureDraftExperience(),o=dx.tradeOffers?.[idx],pick=state.draft.pickIndex+1;if(!o||pick!==o.currentPick||currentDraftTeam()!==userTeam)return;state.draft.order[pick-1]=o.from;if(o.laterPick)state.draft.order[o.laterPick-1]=userTeam;for(const id of o.assets){const a=state.draftAssets.find(x=>x.id===id);if(a&&a.owner===o.from)a.owner=userTeam}dx.tradeHistory.push({type:'trade_down',date:state.date,pick,partner:o.from,laterPick:o.laterPick,assets:[...o.assets]});addTransaction('DRAFT TRADE',`${userTeam} traded pick No. ${pick} to ${o.from} for pick No. ${o.laterPick}${o.assets.length?` plus ${o.assets.length} future pick asset${o.assets.length>1?'s':''}`:''}.`,state.date);dx.tradeOffers=[];cpuDraftOne();persist();renderView();toast('DRAFT-NIGHT TRADE COMPLETE')}
function tradeUpProposal(){const pick=state.draft.pickIndex+1,cpu=currentDraftTeam();if(!cpu||cpu===userTeam)return null;const later=nextOwnedDraftPick(userTeam,pick);if(!later||later-pick>16)return null;const cur=draftPickValue(pick),base=draftPickValue(later),assets=(state.draftAssets||[]).filter(a=>a.owner===userTeam&&a.year>state.seasonYear&&a.tradeable!==false).sort((a,b)=>a.round-b.round||a.year-b.year),send=[];let v=base;for(const a of assets){if(v>=cur*1.02)break;if(a.round===2||cur-v>160){const step=a.round===1?stepienLegal(userTeam,[a]):{ok:true};if(step.ok){send.push(a.id);v+=draftFutureAssetValue(a)}}if(send.length>=2)break}if(v<cur*.96)return null;return {partner:cpu,currentPick:pick,laterPick:later,assets:send,value:+v.toFixed(1),target:+cur.toFixed(1)}}
function executeTradeUp(){const o=tradeUpProposal();if(!o)return;state.draft.order[o.currentPick-1]=userTeam;state.draft.order[o.laterPick-1]=o.partner;for(const id of o.assets){const a=state.draftAssets.find(x=>x.id===id);if(a&&a.owner===userTeam)a.owner=o.partner}const dx=ensureDraftExperience();dx.tradeHistory.push({type:'trade_up',date:state.date,pick:o.currentPick,partner:o.partner,laterPick:o.laterPick,assets:[...o.assets]});addTransaction('DRAFT TRADE',`${userTeam} moved from No. ${o.laterPick} to No. ${o.currentPick} in a draft-night deal with ${o.partner}.`,state.date);persist();renderView();toast(`YOU ARE ON THE CLOCK AT #${o.currentPick}`)}
function cpuDraftOne(){const pick=state.draft.pickIndex+1,tm=currentDraftTeam(),avail=draftAvailable();if(!tm||!avail.length)return;const needs=teamNeeds(tm);let best=[...avail].slice(0,14).sort((a,b)=>{const score=p=>p.draft_projection.potential*.72+overall(p)*.68+((p.positions||[]).some(x=>needs.includes(x))?5:0)+rng()*3;return score(b)-score(a)})[0];signDraftPick(best,tm,pick);const dx=ensureDraftExperience();dx.lastSelection={pick,team:tm,player_id:best.id};dx.tradeOffers=[]}
function userDraftPlayer(id){if(currentDraftTeam()!==userTeam)return;const p=byId.get(id);if(!p||currentStatus(p)!=='draft_prospect')return;const pick=state.draft.pickIndex+1;signDraftPick(p,userTeam,pick);const dx=ensureDraftExperience();dx.lastSelection={pick,team:userTeam,player_id:p.id};dx.tradeOffers=[];persist();renderView();setTop();toast(`${p.name.toUpperCase()} · PICK ${pick}`)}
