function draftTradePanel(){const dx=ensureDraftExperience(),pick=state.draft.pickIndex+1;if(currentDraftTeam()===userTeam){return `<section class="draftTradeRoom"><div><span>DRAFT-NIGHT TRADE ROOM</span><strong>SHOP PICK #${pick}</strong><small>Move down and collect additional draft capital.</small></div><button id="shopDraftPick">GET OFFERS</button>${dx.tradeOffers?.length?`<div class="draftTradeOffers">${dx.tradeOffers.map((o,i)=>`<button data-accept-draft-offer="${i}">${logo(team(o.from))}<div><strong>${o.from} OFFER</strong><span>#${o.laterPick}${o.assets.length?` + ${o.assets.map(id=>{const a=state.draftAssets.find(x=>x.id===id);return a?`${a.year} ${a.round===1?'1ST':'2ND'}`:''}).filter(Boolean).join(' + ')}`:''}</span></div><b>ACCEPT</b></button>`).join('')}</div>`:''}</section>`}const up=tradeUpProposal();return up?`<section class="draftTradeRoom"><div><span>DRAFT-NIGHT TRADE ROOM</span><strong>TRADE UP TO #${pick}</strong><small>Send #${up.laterPick}${up.assets.length?` plus ${up.assets.map(id=>{const a=state.draftAssets.find(x=>x.id===id);return a?`${a.year} ${a.round===1?'1ST':'2ND'}`:''}).filter(Boolean).join(' + ')}`:''} to ${up.partner}.</small></div><button id="tradeUpNow">MAKE OFFER</button></section>`:''}
