  const old=state.livingLeague||{};
  state.livingLeague={version:32,dailyActions:old.dailyActions||{},developmentCredits:old.developmentCredits||{},newsArchive:old.newsArchive||[],actionQueue:old.actionQueue||[],incomingTrades:old.incomingTrades||[],findTradeResults:[],lastProposalDate:old.lastProposalDate||'',lastDigestDate:old.lastDigestDate||'',lastAdvanceDigest:old.lastAdvanceDigest||null,daySerial:old.daySerial||0};
