function incomingOfferCard(p){const from=team(p.from),o=org(p.from),mine=byId.get(p.user_player_id),theirs=byId.get(p.cpu_player_id),pick=(state.draftAssets||[]).find(x=>x.id===p.pick_id);return `<section class="llOffer"><div class="llOfferTop"><div><span>FORMAL TRADE PROPOSAL · ACTION REQUIRED</span><h3>${esc(from?.name||p.from)} are calling</h3><small>${esc(o.lead_executive)} · ${esc(o.executive_title)}</small></div>${logo(from)}</div><div class="llOfferSwap"><div><span>${team(userTeam).abbr} RECEIVE</span><b>${esc(theirs?.name||'Player')}</b><small>${theirs?`${overall(theirs)} OVR · ${money(salaryOf(theirs))}`:''}${pick?` · ${pickLabel(pick)}`:''}</small></div><em>⇄</em><div><span>${from?.abbr||p.from} RECEIVE</span><b>${esc(mine?.name||'Player')}</b><small>${mine?`${overall(mine)} OVR · ${money(salaryOf(mine))}`:''}</small></div></div><div class="llOfferActions"><button data-offer-action="accept" data-offer-id="${p.id}">ACCEPT</button><button data-offer-action="modify" data-offer-id="${p.id}">MODIFY</button><button data-offer-action="decline" data-offer-id="${p.id}">DECLINE</button></div></section>`}
function actionQueue(){const p=formalPending();return p.length?`<section class="llBlock"><div class="llSectionTitle danger"><div><span>FRONT OFFICE INBOX</span><h3>${p.length} Decision${p.length===1?'':'s'} Blocking Advance</h3></div><b>REQUIRED</b></div>${p.map(incomingOfferCard).join('')}</section>`:''}

function leagueNews(){const stories=typeof buildStories==='function'?buildStories():[];const tx=[...state.transactions].filter(x=>x.date>=previousDate(state.date)).slice(-3).reverse();const items=[];for(const x of tx)items.push({tag:ORGS.media?.insider?.host||'BREAKING',head:x.type,copy:x.text});for(const s of stories.slice(0,3))items.push({tag:s.tag,head:s.headline,copy:s.dek});if(!items.length)items.push({tag:'LEAGUE WIRE',head:'The day is still forming',copy:'Games, transactions, injuries and performances will automatically populate this desk as your universe moves.'});return `<section class="llBlock"><div class="llSectionTitle"><div><span>${mediaLabel('nba_today')||'NBA TODAY'} · ${esc(ORGS.media?.nba_today?.host||'MALIKA ANDREWS')}</span><h3>Top Headlines</h3></div><b>SIMULATED</b></div><div class="llHeadlines">${items.slice(0,5).map((x,i)=>`<article class="${i===0?'lead':''}"><span>${esc(x.tag)}</span><h4>${esc(x.head)}</h4><p>${esc(x.copy)}</p></article>`).join('')}</div></section>`}

function orgDirectory(){const c=ORGS.commissioner||{name:'Adam Silver',role:'NBA Commissioner'};return `<section class="llBlock"><div class="llSectionTitle"><div><span>LEAGUE OFFICE + 30 FRONT OFFICES</span><h3>League Organizations</h3></div><b>2026–27</b></div><div class="llCommissioner"><span>NBA COMMISSIONER</span><b>${esc(c.name)}</b><small>${esc(c.role||'League Office')}</small></div><div class="llOrgRail">${teams.map(t=>{const o=org(t.abbr);return `<button data-open-org="${t.abbr}">${logo(t)}<b>${t.abbr}</b><span>${esc(o.lead_executive)}</span><small>${esc(o.head_coach)}</small></button>`}).join('')}</div></section>`}
function studioRoundtable(){const m=ORGS.media?.inside||{},big=topNight(state.date)||topNight(previousDate(state.date)),subject=big?.p?`${big.p.name}: ${big.line.pts||0} points and the league is talking.`:`${team(userTeam).name}: where the franchise goes next.`;return `<section class="llBlock llInside"><div class="llSectionTitle"><div><span>${esc(m.show||'INSIDE THE NBA')} · SIMULATED STUDIO</span><h3>Roundtable</h3></div><b>${esc(m.host||'ERNIE JOHNSON')}</b></div><p>${esc(subject)}</p><div class="llPanelists">${(m.analysts||['Kenny Smith','Shaquille O’Neal','Charles Barkley']).map(n=>`<span>${esc(n)}</span>`).join('')}</div></section>`}

function advanceButton(){if(state.seasonComplete)return `${awardsStrip()}<button class="primaryAction" id="beginPostseason">BEGIN ${state.seasonYear+1} POSTSEASON</button>`;const block=formalPending().length;return `<section class="llAdvance"><div><span>NEXT LEAGUE DAY</span><b>${shortDate(addDays(state.date,1))}</b><small>${block?'Resolve the front-office inbox first.':'Games, news, injuries, transactions and league context will update.'}</small></div><button id="simDay" ${block?'disabled':''}>${block?'ACTION REQUIRED':'ADVANCE DAY →'}</button></section>`}

function preseasonHome(){const count=signedCount(userTeam),cut=Math.max(0,count-15),open=Math.max(0,15-count),five=startingFive(userTeam);return `${hero()}${mediaHero()}${actionQueue()}${teamToday()}${leadershipCard()}<section class="llBlock"><div class="llSectionTitle"><div><span>OPENING NIGHT · ${shortDate(DATES.opening_day)}</span><h3>Roster Status</h3></div><b>${count}/15</b></div>${cut?`<div class="notice danger"><strong>${cut} roster cut${cut>1?'s':''} required.</strong> Get to 15 players before opening night.</div>`:open?`<div class="notice warn"><strong>${open} roster spot${open>1?'s':''} open.</strong> Fill the 15-man roster before starting.</div>`:`<div class="notice good"><strong>Opening-night roster ready.</strong> You have 15 players.</div>`}<button class="primaryAction ${cut||open?'disabled':''}" id="startSeason" ${cut||open?'disabled':''}>START ${CAP.season} SEASON</button></section>${leagueNews()}${studioRoundtable()}${socialFeed()}<div class="sectionHead"><h2>Starting Five</h2><button class="linkBtn" data-jump="roster">FULL ROSTER</button></div><div class="five">${five.map(starterCard).join('')}</div>${orgDirectory()}`}
function livingHome(){if(state.phase==='playin'||state.phase==='playoffs'||state.phase==='champion')return postseasonHome();if(state.phase==='lottery')return lotteryView();if(state.phase==='scouting')return scoutingView();if(state.phase==='draft')return draftHome();if(state.phase==='free_agency')return freeAgencyHome();if(state.phase==='training_camp')return trainingCampHome();ll();if(!state.seasonStarted)return preseasonHome();const meet=pendingMeetings()[0],medical=activeTeamInjuries(userTeam);return `${hero()}${mediaHero()}${actionQueue()}${meet?`<div class="sectionHead"><h2>Player Meeting</h2><span>NEEDS YOUR ATTENTION</span></div>${meetingCard(meet)}`:''}${medical.length?`<div class="sectionHead"><h2>Medical Report</h2><button class="linkBtn" data-jump="roster">MANAGE ROTATION</button></div>${medicalReport(userTeam,3)}`:''}${teamToday()}${advanceButton()}${leagueNews()}${aroundLeague()}${studioRoundtable()}${socialFeed()}${leadershipCard()}${orgDirectory()}`}

function generateIncomingTrade(d,{force=false}={}){
 const L=ll();if(!L||!state.seasonStarted||d>DATES.trade_deadline||formalPending().length)return null;
 if(!force&&!L.lastProposalDate&&d>=DATES.opening_day&&daysBetween(DATES.opening_day,d)>=10)force=true;
 const since=L.lastProposalDate?daysBetween(L.lastProposalDate,d):99,near=daysBetween(d,DATES.trade_deadline)<=14;if(!force&&since<(near?4:9))return null;
 const chance=near?.14:.055;if(!force&&rng()>chance)return null;
 const mine=teamPlayers(userTeam,{activeOnly:true}).filter(p=>!currentTradeRestriction(p)&&boardStatus(p)!=='untouchable'&&overall(p)>=69&&overall(p)<=89).sort((a,b)=>{const aa=boardStatus(a)==='shop'?1:0,bb=boardStatus(b)==='shop'?1:0;return bb-aa||Math.abs(overall(a)-77)-Math.abs(overall(b)-77)});
 for(const target of mine){
  const partners=[...teams].filter(t=>t.abbr!==userTeam).sort(()=>rng()-.5);
  for(const t of partners){
   const returns=teamPlayers(t.abbr,{activeOnly:true}).filter(p=>!currentTradeRestriction(p)&&cpuAvailability(p,t.abbr)!=='untouchable').sort((a,b)=>Math.abs(salaryOf(a)-salaryOf(target))-Math.abs(salaryOf(b)-salaryOf(target)));
   for(const filler of returns){
    const c=cpuTradeCbaCheck(userTeam,t.abbr,target,filler);if(!c.ok)continue;
    const cpuGets=playerTradeValue(target,t.abbr),cpuGives=playerTradeValue(filler,t.abbr);if(cpuGets<cpuGives*.94)continue;
    let pick=null;if(cpuGets>cpuGives+12){const ps=pickAssets(t.abbr,{tradeableOnly:true}).filter(x=>x.round===2&&stepienLegal(t.abbr,[x]).ok).sort((a,b)=>pickTradeValue(a,userTeam)-pickTradeValue(b,userTeam));pick=ps.find(x=>cpuGets>=cpuGives+pickTradeValue(x,t.abbr)*.85)||null}
    const proposal={id:`LL-OFFER-${d}-${t.abbr}-${target.id}`,date:d,from:t.abbr,user_player_id:target.id,cpu_player_id:filler.id,pick_id:pick?.id||null,status:'pending'};L.incomingTrades.unshift(proposal);L.lastProposalDate=d;return proposal;
   }
  }
 }
 return null;
}
function resolveOffer(id,action){const L=ll(),p=L?.incomingTrades.find(x=>x.id===id);if(!p||p.status!=='pending')return;const mine=byId.get(p.user_player_id),theirs=byId.get(p.cpu_player_id),pick=(state.draftAssets||[]).find(x=>x.id===p.pick_id);if(action==='decline'){p.status='declined';p.resolved=state.date;persist();renderView();toast('TRADE DECLINED');return}if(action==='modify'){p.status='modified';p.resolved=state.date;tradePartner=p.from;tradeMine.clear();tradeTheirs.clear();if(mine)tradeMine.add('P|'+mine.id);if(theirs)tradeTheirs.add('P|'+theirs.id);if(pick)tradeTheirs.add('K|'+pick.id);currentView='trade';persist();renderView();scrollTo({top:0,behavior:'smooth'});toast('OFFER LOADED · MODIFY TERMS');return}const c=mine&&theirs?cpuTradeCbaCheck(userTeam,p.from,mine,theirs):{ok:false,reason:'ASSET MISSING'};if(!c.ok){p.status='invalidated';p.resolved=state.date;persist();renderView();toast('OFFER NO LONGER CBA-LEGAL');return}if(cpuExecuteTrade(userTeam,p.from,mine,theirs,pick,state.date,c)){p.status='accepted';p.resolved=state.date;persist();renderView();toast('TRADE ACCEPTED')}}

function findTradesPanel(){const L=ll(),selected=[...tradeMine].filter(x=>x.startsWith('P|')).map(x=>byId.get(x.slice(2))).filter(Boolean),results=L?.findTradeResults||[];return `<section class="llFindTrades"><div><span>TRADE DESK</span><h3>Find Me Trades</h3><p>Select one of your players, then ask the league for five CBA-legal offers the CPU teams would accept.</p></div><button id="findMeTrades" ${selected.length!==1?'disabled':''}>${selected.length===1?'FIND 5 TRADES':'SELECT 1 PLAYER'}</button>${results.length?`<div class="llTradeResults">${results.map((r,i)=>{const t=team(r.team),p=byId.get(r.cpu_player_id),pick=(state.draftAssets||[]).find(x=>x.id===r.pick_id);return `<button data-load-found-trade="${i}">${logo(t)}<div><span>${t.abbr} · ${esc(org(t.abbr).lead_executive)}</span><b>${esc(p?.name||'Player')}${pick?` + ${esc(pickLabel(pick))}`:''}</b><small>CBA LEGAL · CPU ACCEPTS</small></div><em>LOAD</em></button>`}).join('')}</div>`:''}</section>`}
function generateFindTrades(){const L=ll(),selected=[...tradeMine].filter(x=>x.startsWith('P|')).map(x=>byId.get(x.slice(2))).filter(Boolean);if(selected.length!==1){toast('SELECT ONE OF YOUR PLAYERS FIRST');return}const target=selected[0],candidates=[],seen=new Set();for(const t of teams){if(t.abbr===userTeam)continue;for(const p of teamPlayers(t.abbr,{activeOnly:true})){if(currentTradeRestriction(p)||cpuAvailability(p,t.abbr)==='untouchable')continue;const c=cpuTradeCbaCheck(userTeam,t.abbr,target,p);if(!c.ok)continue;const gets=playerTradeValue(target,t.abbr),gives=playerTradeValue(p,t.abbr);if(gets<gives*.94)continue;const userGive=playerTradeValue(target,userTeam),userGet=playerTradeValue(p,userTeam),balance=Math.abs(userGive-userGet);let pick=null;if(gets>gives+14){const ps=pickAssets(t.abbr,{tradeableOnly:true}).filter(x=>x.round===2&&stepienLegal(t.abbr,[x]).ok).sort((a,b)=>pickTradeValue(a,userTeam)-pickTradeValue(b,userTeam));pick=ps.find(x=>gets>=gives+pickTradeValue(x,t.abbr)*.9)||null}const score=balance+(pick?Math.abs(userGive-(userGet+pickTradeValue(pick,userTeam))):0)*.4,key=`${t.abbr}|${p.id}|${pick?.id||''}`;if(seen.has(key))continue;seen.add(key);candidates.push({team:t.abbr,cpu_player_id:p.id,pick_id:pick?.id||null,score})}}
 candidates.sort((a,b)=>a.score-b.score);
 // Prefer five different front offices first, then use additional acceptable frameworks if needed.
 const chosen=[],usedTeams=new Set();for(const r of candidates){if(usedTeams.has(r.team))continue;chosen.push(r);usedTeams.add(r.team);if(chosen.length===5)break}if(chosen.length<5){for(const r of candidates){if(chosen.includes(r))continue;chosen.push(r);if(chosen.length===5)break}}
 L.findTradeResults=chosen;persist();renderView();toast(L.findTradeResults.length===5?'5 ACCEPTABLE TRADES FOUND':`${L.findTradeResults.length} ACCEPTABLE TRADES FOUND`)}
function loadFoundTrade(i){const r=ll()?.findTradeResults?.[i];if(!r)return;const selected=[...tradeMine].find(x=>x.startsWith('P|'));tradePartner=r.team;tradeMine.clear();if(selected)tradeMine.add(selected);tradeTheirs.clear();tradeTheirs.add('P|'+r.cpu_player_id);if(r.pick_id)tradeTheirs.add('K|'+r.pick_id);renderView();toast('CPU-ACCEPTABLE FRAMEWORK LOADED')}

function orgSheet(a){const t=team(a),o=org(a),assist=(o.assistants||[]);return `<div class="llSheetBackdrop" id="llSheetBackdrop"><section class="llSheet"><button class="llSheetClose" id="llSheetClose">×</button><div class="llSheetBrand">${logo(t)}<div><span>${esc(t?.name||a)}</span><h2>Organization</h2></div></div><div class="llOrgRows"><div><span>PRIMARY OWNER</span><b>${esc(o.owner)}</b>${o.governor&&o.governor!==o.owner?`<small>Governor · ${esc(o.governor)}</small>`:''}</div><div><span>LEAD BASKETBALL EXECUTIVE</span><b>${esc(o.lead_executive)}</b><small>${esc(o.executive_title)}</small></div>${o.general_manager&&o.general_manager!==o.lead_executive?`<div><span>GENERAL MANAGER</span><b>${esc(o.general_manager)}</b></div>`:''}<div><span>HEAD COACH</span><b>${esc(o.head_coach)}</b></div></div><div class="llAssistants"><span>KEY COACHING STAFF</span>${assist.map((n,i)=>`<div><b>${esc(n)}</b><small>${i===0?'Lead / key assistant':'Assistant Coach'}</small></div>`).join('')}${(o.advisors||[]).map(n=>`<div><b>${esc(n)}</b><small>Coaching Advisor</small></div>`).join('')}</div>${o.ownership_status?`<div class="llOwnershipStatus"><b>OWNERSHIP NOTE</b><span>${esc(o.ownership_status)}</span></div>`:''}<div class="llOrgIdentity"><span>CPU TEAM DIRECTION</span><b>${esc(teamDirection(a).label)}</b><p>${esc(teamDirection(a).summary)}</p></div></section></div>`}
function openOrg(a){document.getElementById('llSheetBackdrop')?.remove();document.body.insertAdjacentHTML('beforeend',orgSheet(a));const close=()=>document.getElementById('llSheetBackdrop')?.remove();document.getElementById('llSheetClose').onclick=close;document.getElementById('llSheetBackdrop').onclick=e=>{if(e.target.id==='llSheetBackdrop')close()}}


/* v0.32 — Daily Broadcast Presentation Overhaul */
function actionIcon(id){return ({practice:'↗',shooting:'◎',defense:'◆',recovery:'＋',film:'▶',development:'★'})[id]||'•'}
function showSlug(desk=''){const x=String(desk).toLowerCase();if(x.includes('sportscenter'))return'sportscenter';if(x.includes('nba today'))return'nbatoday';if(x.includes('inside'))return'inside';if(x.includes('breaking'))return'breaking';return'courtside'}
function dailyMasthead(){
 const t=team(userTeam),r=record(userTeam),g=userGameToday(),pending=formalPending().length,slate=todayGames().filter(x=>!resultFor(x)).length,moves=state.transactions.filter(x=>x.date===state.date).length;
 const status=g?`${g.home===userTeam?'HOME':'AWAY'} · ${team(g.home===userTeam?g.away:g.home)?.abbr||''}`:activeDailyAction()?.label||'OFF DAY';
 return `<section class="bcMasthead"><div class="bcLiveBar"><div><i></i><b>NBA COURTSIDE LIVE</b></div><span>2026–27 LEAGUE DAY</span></div><div class="bcDateRow"><div><span>${dayName(state.date)}</span><h1>${dateFmt(state.date)}</h1></div><div class="bcClubChip">${logo(t)}<div><b>${t.abbr}</b><span>${state.seasonStarted?`${r.w}–${r.l} · ${t.conference}`:'PRESEASON'}</span></div></div></div><div class="bcRundown"><button data-jump="home"><span>YOUR DAY</span><b>${esc(status)}</b></button><button data-jump="league" data-open-pulse="1"><span>NBA SLATE</span><b>${slate} UPCOMING</b></button><button data-jump="trade"><span>FRONT OFFICE</span><b class="${pending?'hot':''}">${pending?`${pending} REQUIRED`:'INBOX CLEAR'}</b></button><button data-jump="league" data-open-pulse="1"><span>LEAGUE WIRE</span><b>${moves} MOVES</b></button></div></section>`
}
function buildAdvanceDigest(from,to){
 const top=topNight(to),inj=(state.injuryHistory||[]).filter(x=>x.start_date===to).length;
 return {from,to,finals:completedOn(to).length,moves:state.transactions.filter(x=>x.date===to).length,injuries:inj,offers:formalPending().length,topName:top?.p?.name||'',topLine:top?.line?`${top.line.pts||0} PTS · ${top.line.reb||0} REB · ${top.line.ast||0} AST`:''};
}
function dayDigest(){const d=ll()?.lastAdvanceDigest;if(!d||d.to!==state.date)return'';const chips=[[d.finals,'FINALS'],[d.moves,'TRANSACTIONS'],[d.injuries,'INJURY UPDATES'],[d.offers,'GM ACTIONS']];return `<section class="bcDigest"><div class="bcDigestTitle"><span>SINCE YOUR LAST ADVANCE</span><b>THE LEAGUE MOVED.</b></div><div class="bcDigestStats">${chips.map(x=>`<div><b>${x[0]}</b><span>${x[1]}</span></div>`).join('')}</div>${d.topName?`<div class="bcDigestLead"><span>PERFORMANCE WATCH</span><b>${esc(d.topName)}</b><small>${esc(d.topLine)}</small></div>`:''}</section>`}
function leagueWire(){
 const items=[],pending=formalPending()[0],tx=[...state.transactions].filter(x=>x.date===state.date||x.date===previousDate(state.date)).slice(-3).reverse();
 if(pending)items.push({tag:'BREAKING',text:`${team(pending.from)?.abbr||pending.from} sent a formal trade proposal — action required.`});
 for(const x of tx)items.push({tag:x.type||'MOVE',text:x.text});
 for(const g of completedOn(state.date).slice(0,3)){const r=resultFor(g);items.push({tag:'FINAL',text:`${g.away} ${r?.away_score??'—'} · ${g.home} ${r?.home_score??'—'}`})}
 const ng=nextGame(userTeam);if(ng)items.push({tag:'NEXT',text:`${team(userTeam).abbr} ${ng.home===userTeam?'vs':'@'} ${ng.home===userTeam?ng.away:ng.home} · ${shortDate(ng.date)}`});
 if(!items.length)items.push({tag:'WIRE',text:'The league day is open. Results, moves and medical updates will populate here.'});
 return `<section class="bcWire"><div class="bcWireLabel">LEAGUE WIRE</div><div class="bcWireRail">${items.slice(0,7).map(x=>`<div><b>${esc(x.tag)}</b><span>${esc(x.text)}</span></div>`).join('')}</div></section>`
}
function leadStory(){
 const pending=formalPending()[0];
 if(pending){const t=team(pending.from),o=org(pending.from),mine=byId.get(pending.user_player_id),theirs=byId.get(pending.cpu_player_id);return {desk:'BREAKING NEWS',host:ORGS.media?.insider?.host||'COURTSIDE INSIDER',eyebrow:'FRONT OFFICE ALERT',headline:`${t?.name||pending.from} make the call`,dek:`${o.lead_executive} has sent a formal offer centered on ${theirs?.name||'a player'} for ${mine?.name||'one of your players'}. The league day cannot move until you respond.`,tone:'breaking',visual:{type:'teams',a:pending.from,b:userTeam}}}
 const ug=userGameToday();
 if(ug){const opp=ug.home===userTeam?ug.away:ug.home,t=team(opp);return {desk:mediaLabel('nba_today')||'NBA TODAY',host:ORGS.media?.nba_today?.host||'MALIKA ANDREWS',eyebrow:ug.cup_championship?'NBA CUP CHAMPIONSHIP':'TONIGHT',headline:`${team(userTeam).abbr} ${ug.neutral_site?'vs':ug.home===userTeam?'host':'visit'} ${t?.abbr}`,dek:`${record(userTeam).w}–${record(userTeam).l} ${team(userTeam).abbr} enter a live league slate with ${todayGames().filter(g=>!resultFor(g)).length} games still on the board.`,tone:'game',visual:{type:'teams',a:userTeam,b:opp}}}
 const big=topNight(state.date)||topNight(previousDate(state.date));
 if(big?.p){const ta=team(currentTeam(big.p));return {desk:mediaLabel('sportscenter')||'SPORTSCENTER',host:ORGS.media?.sportscenter?.host||'SCOTT VAN PELT',eyebrow:'TOP STORY',headline:`${big.p.name} owns the night`,dek:`${big.line.pts||0} PTS · ${big.line.reb||0} REB · ${big.line.ast||0} AST for ${ta?.abbr||''}. One performance is driving the league conversation.`,tone:'feature',visual:{type:'player',player:big.p,team:ta?.abbr}}}
 const t=team(userTeam),o=org(userTeam),star=topPlayers(userTeam,1)[0];return {desk:'COURTSIDE DAILY',host:o.head_coach,eyebrow:state.seasonStarted?'OFF-DAY EDITION':'PRESEASON DESK',headline:state.seasonStarted?`${t.name}: make the day count`:`${t.name} report to work`,dek:state.seasonStarted?'No game does not mean no league. Training, transactions, injuries, scouting and stories continue around your franchise.':`${o.lead_executive}, ${o.head_coach} and the front office are building toward Opening Night.`,tone:'quiet',visual:star?{type:'player',player:star,team:userTeam}:{type:'team',team:userTeam}};
}
function storyVisual(v){if(!v)return'';if(v.type==='player'&&v.player)return `<div class="bcHeroPlayer" style="--club:${team(v.team)?.primary_color||'#242a3a'}">${img(v.player)}<span>${esc(team(v.team)?.abbr||'NBA')}</span></div>`;if(v.type==='teams'){const a=team(v.a),b=team(v.b);return `<div class="bcHeroMatch">${logo(a)}<b>VS</b>${logo(b)}</div>`}const t=team(v.team);return `<div class="bcHeroTeam">${logo(t)}<b>${esc(t?.abbr||'NBA')}</b></div>`}
function mediaHero(){const s=leadStory(),slug=showSlug(s.desk);return `<section class="bcHero ${slug} ${s.tone}"><div class="bcProgram"><div><span>${esc(s.desk)}</span><b>${esc(s.host)}</b></div><small>SIMULATED COVERAGE</small></div><div class="bcHeroBody"><div class="bcHeroCopy"><span>${esc(s.eyebrow)}</span><h2>${esc(s.headline)}</h2><p>${esc(s.dek)}</p></div><div class="bcHeroVisual">${storyVisual(s.visual)}</div></div><div class="bcHeroLower"><b>${dayName(state.date)} · ${shortDate(state.date)}</b><span>${completedOn(state.date).length} FINAL · ${todayGames().filter(g=>!resultFor(g)).length} TO PLAY · ${formalPending().length} ACTION</span></div></section>`}
function teamAlerts(){const meet=pendingMeetings()[0],medical=activeTeamInjuries(userTeam);if(!meet&&!medical.length)return'';return `<section class="bcTeamAlerts"><div class="bcModuleHead"><div><span>CLUB DESK</span><h3>Needs Your Attention</h3></div><b>${(meet?1:0)+medical.length} ITEM${(meet?1:0)+medical.length===1?'':'S'}</b></div>${meet?`<div class="bcAlertGroup"><span>PLAYER MEETING</span>${meetingCard(meet)}</div>`:''}${medical.length?`<div class="bcAlertGroup"><div class="bcAlertRow"><span>MEDICAL REPORT</span><button data-jump="roster">MANAGE ROTATION</button></div>${medicalReport(userTeam,3)}</div>`:''}</section>`}
function teamToday(){
 const g=userGameToday(),done=activeDailyAction();
 if(g)return `<section class="bcTeamToday game"><div class="bcModuleHead"><div><span>YOUR TEAM TODAY · GAME CENTER</span><h3>${g.cup_championship?'NBA Cup Championship':'Tonight’s Assignment'}</h3></div><b>${shortDate(g.date)}</b></div>${gameCard(g)}</section>`;
 return `<section class="bcTeamToday training"><div class="bcModuleHead"><div><span>YOUR TEAM TODAY · TRAINING CENTER</span><h3>${state.seasonStarted?'No Game Scheduled':'Preseason Workday'}</h3></div><b>${done?'PLAN LOCKED':'CHOOSE PLAN'}</b></div><p class="bcModuleDek">An off day is still a franchise day. Choose how the club uses it before you move through the calendar.</p>${done?`<div class="bcActivityDone"><div>${actionIcon(done.id)}</div><span><b>${esc(done.label)}</b><small>${esc(ACTIONS[done.id]?.note||'Today’s work is logged.')}</small></span></div>`:`<div class="bcActivityGrid">${Object.entries(ACTIONS).map(([id,a])=>`<button data-daily-action="${id}"><i>${actionIcon(id)}</i><span><b>${a.label}</b><small>${a.sub}</small></span><em>SELECT</em></button>`).join('')}</div>`}</section>`
}
function performanceCards(){
 const d=completedOn(state.date).length?state.date:previousDate(state.date),rows=[];for(const g of completedOn(d)){const r=resultFor(g);if(!r)continue;const top=r.top||[...(r.box?.home||[]),...(r.box?.away||[])].sort((a,b)=>(b.pts||0)-(a.pts||0))[0];const p=top&&byId.get(top.player_id);rows.push({g,r,top,p})}rows.sort((a,b)=>(b.top?.pts||0)-(a.top?.pts||0));
 if(!rows.length)return `<div class="bcEmpty"><b>NO FINALS YET</b><span>SportsCenter fills automatically when the league produces results.</span></div>`;
 const lead=rows[0],lp=lead.p,lt=lp?team(currentTeam(lp)):null;const rest=rows.slice(1,6);
 return `<div class="bcPerformanceLead" ${lp?`data-player="${lp.id}"`:''}><div class="bcPerformanceFace">${lp?img(lp):logo(team(lead.r.winner))}</div><div class="bcPerformanceCopy"><span>PERFORMANCE OF THE NIGHT</span><h4>${esc(lp?.name||team(lead.r.winner)?.name||'Final')}</h4><div><b>${lead.top?.pts||0}<small>PTS</small></b><b>${lead.top?.reb||0}<small>REB</small></b><b>${lead.top?.ast||0}<small>AST</small></b></div><p>${lead.g.away} ${lead.r.away_score} · ${lead.g.home} ${lead.r.home_score}${lt?` · ${lt.abbr}`:''}</p></div></div><div class="bcScoreRail">${rest.map(x=>{const w=team(x.r.winner),p=x.p;return `<button ${p?`data-player="${p.id}"`:''}><span>FINAL · ${x.g.away} ${x.r.away_score} · ${x.g.home} ${x.r.home_score}</span><b>${esc(p?.name||w?.name||'Final')}</b><small>${x.top?`${x.top.pts||0} PTS · ${x.top.reb||0} REB · ${x.top.ast||0} AST`:'FINAL'}</small></button>`}).join('')}</div>`
}
function aroundLeague(){return `<section class="bcShow bcSportsCenter"><div class="bcShowHead"><div class="bcShowBrand"><span>SPORTSCENTER</span><small>WITH ${esc(ORGS.media?.sportscenter?.host||'SCOTT VAN PELT')}</small></div><button data-jump="league" data-open-pulse="1">FULL LEAGUE PULSE →</button></div>${performanceCards()}</section>`}
function leagueNews(){const stories=typeof buildStories==='function'?buildStories():[],tx=[...state.transactions].filter(x=>x.date>=previousDate(state.date)).slice(-3).reverse(),items=[];for(const x of tx)items.push({tag:ORGS.media?.insider?.host||'BREAKING',head:x.type,copy:x.text,hot:true});for(const s of stories.slice(0,4))items.push({tag:s.tag,head:s.headline,copy:s.dek});if(!items.length)items.push({tag:'LEAGUE WIRE',head:'The day is still forming',copy:'Games, transactions, injuries and performances will populate this desk as your universe moves.'});const lead=items[0],rest=items.slice(1,5);return `<section class="bcShow bcNBAToday"><div class="bcShowHead"><div class="bcShowBrand"><span>NBA TODAY</span><small>${esc(ORGS.media?.nba_today?.host||'MALIKA ANDREWS')} · SIMULATED STUDIO</small></div><b>HEADLINES</b></div><article class="bcHeadlineLead ${lead.hot?'hot':''}"><span>${esc(lead.tag)}</span><h4>${esc(lead.head)}</h4><p>${esc(lead.copy)}</p></article><div class="bcHeadlineList">${rest.map((x,i)=>`<article><em>${String(i+2).padStart(2,'0')}</em><div><span>${esc(x.tag)}</span><b>${esc(x.head)}</b><small>${esc(x.copy)}</small></div></article>`).join('')}</div></section>`}
function studioRoundtable(){const m=ORGS.media?.inside||{},big=topNight(state.date)||topNight(previousDate(state.date)),subject=big?.p?`${big.p.name} put ${big.line.pts||0} on the board. What does the night mean for ${team(currentTeam(big.p))?.name||'the race'}?`:`${team(userTeam).name}: what should the front office prioritize next?`;const analysts=m.analysts||['Kenny Smith','Shaquille O’Neal','Charles Barkley'];return `<section class="bcShow bcInside"><div class="bcShowHead"><div class="bcShowBrand"><span>INSIDE THE NBA</span><small>${esc(m.host||'ERNIE JOHNSON')} · SIMULATED ROUNDTABLE</small></div><b>STUDIO</b></div><div class="bcInsideTopic"><span>TONIGHT’S QUESTION</span><h4>${esc(subject)}</h4></div><div class="bcPanelists"><div class="host"><i>EJ</i><span><b>${esc(m.host||'Ernie Johnson')}</b><small>HOST</small></span></div>${analysts.map(n=>`<div><i>${n.split(/\s+/).map(x=>x[0]).slice(0,2).join('')}</i><span><b>${esc(n)}</b><small>ANALYST</small></span></div>`).join('')}</div></section>`}
function socialFeed(){const items=feedItems();return `<section class="bcShow bcSocial"><div class="bcShowHead"><div class="bcShowBrand"><span>COURTSIDE SOCIAL</span><small>X / TWITTER-STYLE · SIMULATED FEED</small></div><b>LIVE</b></div><div class="bcSocialFeed">${items.map(x=>{const init=x.who.replace('@','').split(/\s+/).map(y=>y[0]).slice(0,2).join('').toUpperCase();return `<article class="${x.kind}"><i>${esc(init||'NBA')}</i><div><div class="bcPostMeta"><b>${esc(x.who)}</b><span>${esc(x.handle)}</span></div><p>${esc(x.text)}</p><small>♡  ·  ↻  ·  ◌</small></div></article>`}).join('')}</div></section>`}
function advanceButton(){if(state.seasonComplete)return `${awardsStrip()}<button class="primaryAction" id="beginPostseason">BEGIN ${state.seasonYear+1} POSTSEASON</button>`;const block=formalPending().length,next=addDays(state.date,1),slate=games.filter(g=>g.date===next).length;return `<section class="bcAdvance"><div><span>ADVANCE THE LEAGUE</span><h3>${dayName(next)} · ${shortDate(next)}</h3><p>${block?'A formal front-office decision is blocking the calendar.':`${slate} NBA game${slate===1?'':'s'} scheduled. News, injuries, transactions and performances will evolve.`}</p></div><button id="simDay" ${block?'disabled':''}><span>${block?'ACTION REQUIRED':'NEXT DAY'}</span><b>${block?'!':'→'}</b></button></section>`}
function preseasonHome(){const count=signedCount(userTeam),cut=Math.max(0,count-15),open=Math.max(0,15-count),five=startingFive(userTeam);return `<div class="bcPage">${dailyMasthead()}${leagueWire()}${mediaHero()}${actionQueue()}${teamToday()}${leadershipCard()}<section class="bcRosterGate"><div class="bcModuleHead"><div><span>OPENING NIGHT · ${shortDate(DATES.opening_day)}</span><h3>Roster Status</h3></div><b>${count}/15</b></div>${cut?`<div class="notice danger"><strong>${cut} roster cut${cut>1?'s':''} required.</strong> Get to 15 players before opening night.</div>`:open?`<div class="notice warn"><strong>${open} roster spot${open>1?'s':''} open.</strong> Fill the 15-man roster before starting.</div>`:`<div class="notice good"><strong>Opening-night roster ready.</strong> You have 15 players.</div>`}<button class="primaryAction ${cut||open?'disabled':''}" id="startSeason" ${cut||open?'disabled':''}>START ${CAP.season} SEASON</button></section>${leagueNews()}${studioRoundtable()}${socialFeed()}<div class="sectionHead"><h2>Starting Five</h2><button class="linkBtn" data-jump="roster">FULL ROSTER</button></div><div class="five">${five.map(starterCard).join('')}</div>${orgDirectory()}</div>`}
function livingHome(){if(state.phase==='playin'||state.phase==='playoffs'||state.phase==='champion')return postseasonHome();if(state.phase==='lottery')return lotteryView();if(state.phase==='scouting')return scoutingView();if(state.phase==='draft')return draftHome();if(state.phase==='free_agency')return freeAgencyHome();if(state.phase==='training_camp')return trainingCampHome();ll();if(!state.seasonStarted)return preseasonHome();return `<div class="bcPage">${dailyMasthead()}${dayDigest()}${leagueWire()}${mediaHero()}${actionQueue()}${teamAlerts()}${teamToday()}${advanceButton()}${leagueNews()}${aroundLeague()}${studioRoundtable()}${socialFeed()}${leadershipCard()}${orgDirectory()}</div>`}

// Core overrides.
const oldHome=homeView;homeView=livingHome;
const oldTrade=tradeView;tradeView=function(){const base=oldTrade();if(!tradeOpen())return base;const contact=org(tradePartner||teams.find(t=>t.abbr!==userTeam)?.abbr);return `<section class="llTradeContact"><span>GM-TO-GM LINE</span><b>${esc(contact.lead_executive)}</b><small>${esc(contact.executive_title)} · ${esc(team(tradePartner)?.name||'')}</small></section>${findTradesPanel()}${base}`};
const oldGameCard=gameCard;gameCard=function(g){return oldGameCard(g).replaceAll('v=0.31','v=0.41')};
const oldBind=bindDynamic;bindDynamic=function(){oldBind();document.querySelectorAll('[data-daily-action]').forEach(b=>b.onclick=()=>applyDailyAction(b.dataset.dailyAction));document.querySelectorAll('[data-open-org]').forEach(b=>b.onclick=()=>openOrg(b.dataset.openOrg));document.querySelectorAll('[data-offer-action]').forEach(b=>b.onclick=()=>resolveOffer(b.dataset.offerId,b.dataset.offerAction));if($('#findMeTrades'))$('#findMeTrades').onclick=generateFindTrades;document.querySelectorAll('[data-load-found-trade]').forEach(b=>b.onclick=()=>loadFoundTrade(+b.dataset.loadFoundTrade))};
const oldBindTradeV32=bindTrade;bindTrade=function(){oldBindTradeV32();document.querySelectorAll('[data-asset]').forEach(b=>{const prior=b.onclick;b.onclick=e=>{const L=ll();if(L)L.findTradeResults=[];return prior?.call(b,e)}});document.querySelectorAll('[data-partner]').forEach(b=>{const prior=b.onclick;b.onclick=e=>{const L=ll();if(L)L.findTradeResults=[];return prior?.call(b,e)}})};
const oldSimDay=simNextDay;simNextDay=function(){if(formalPending().length){toast('ACTION REQUIRED · RESOLVE TRADE OFFER');return}const before=state.date,target=addDays(state.date,1);advanceTo(target);if(state.date!==before){const L=ll();L.daySerial++;generateIncomingTrade(state.date);L.lastAdvanceDigest=buildAdvanceDigest(before,state.date);persist();renderView();toast(`${dayName(state.date)} · THE LEAGUE MOVED`)}};

// Keep long-range simulation available elsewhere, but a formal proposal always blocks it.
const oldSimNextGame=simToNextGame;simToNextGame=function(){if(formalPending().length){toast('ACTION REQUIRED · RESOLVE TRADE OFFER');return}oldSimNextGame()};
const oldSimWeek=simWeek;simWeek=function(){if(formalPending().length){toast('ACTION REQUIRED · RESOLVE TRADE OFFER');return}oldSimWeek()};

// Add a modest recovery effect to quick-sim injury risk without touching player ratings.
const oldInjuryRisk=injuryRisk;injuryRisk=function(p,minutes=28){let r=oldInjuryRisk(p,minutes);const L=ll();if(currentTeam(p)===userTeam&&L?.dailyActions?.[state.date]?.id==='recovery')r*=.82;return r};

