/* v0.35 — COLLEGE + DRAFT WORLD */
const CD35=window.NBA_COURTSIDE_COLLEGE_DRAFT_V35||{programs:[],prospects:[]};
let collegeTabV35='board';
let collegeFilterV35='all';
const collegeProgramMapV35=new Map((CD35.programs||[]).map(x=>[x.id,x]));
const collegeProspectMapV35=new Map((CD35.prospects||[]).map(x=>[x.id,x]));
function collegeCycleYearV35(){const old=state?.collegeDraft?.seasonYear;if(state?.seasonStarted&&old!=null&&state.seasonYear>old)return state.seasonYear;return old??state.seasonYear}
function collegeHashV35(s){let h=2166136261>>>0;for(let i=0;i<String(s).length;i++){h^=String(s).charCodeAt(i);h=Math.imul(h,16777619)}return (h>>>0)/4294967296}
function college35(){
 if(!state)return null;const old=state.collegeDraft||{},cycle=collegeCycleYearV35();
 if(old.version!==35||(state.seasonStarted&&old.seasonYear!==state.seasonYear)){
  const archive=[...(old.archive||[])];if(old.version&&old.seasonYear!=null)archive.unshift({seasonYear:old.seasonYear,records:old.records||{},stats:old.stats||{},results:(old.results||[]).slice(-120),stock:old.stock||{}});
  state.collegeDraft={version:35,seasonYear:state.seasonYear,draftYear:state.seasonYear+1,records:{},results:[],stats:{},stock:{},stockHistory:{},scouting:{},watchlist:old.watchlist||[],scoutingCredits:6,scoutingWeek:'',lastProcessedDate:`${state.seasonYear}-11-01`,news:[],archive:archive.slice(0,5),scheduleMode:'simulated_tracked_program_world',sourceClass:state.seasonYear===2026?'source_backed_2027_watch':'future_generated'};
 }
 const C=state.collegeDraft;C.records=C.records||{};C.results=C.results||[];C.stats=C.stats||{};C.stock=C.stock||{};C.stockHistory=C.stockHistory||{};C.scouting=C.scouting||{};C.watchlist=C.watchlist||[];C.news=C.news||[];
 for(const t of CD35.programs||[])if(!C.records[t.id])C.records[t.id]={w:0,l:0,gp:0,pf:0,pa:0,last5:[]};
 for(const p of CD35.prospects||[]){if(C.stock[p.id]==null)C.stock[p.id]=0;if(C.scouting[p.id]==null)C.scouting[p.id]=p.rank<=5?28:p.rank<=14?18:10;if(!C.stats[p.id])C.stats[p.id]={gp:0,pts:0,reb:0,ast:0,stl:0,blk:0,tov:0,last:[]}}
 return C;
}
function collegeWeekKeyV35(date){const d=new Date(date+'T12:00:00'),one=new Date(d.getFullYear(),0,1),week=Math.ceil((((d-one)/86400000)+one.getDay()+1)/7);return `${d.getFullYear()}-${week}`}
function refreshCollegeScoutingV35(){const C=college35(),wk=collegeWeekKeyV35(state.date);if(C.scoutingWeek!==wk){C.scoutingWeek=wk;C.scoutingCredits=6}}
function collegeProgramV35(id){return collegeProgramMapV35.get(id)}
function collegeRecordV35(id){const r=college35()?.records?.[id]||{w:0,l:0,gp:0};return `${r.w}-${r.l}`}
function collegeBoardV35(){const C=college35();return [...(CD35.prospects||[])].sort((a,b)=>{const as=(a.rank-(C.stock[a.id]||0)*1.7),bs=(b.rank-(C.stock[b.id]||0)*1.7);return as-bs||a.rank-b.rank})}
function collegeRankMapV35(){return new Map(collegeBoardV35().map((p,i)=>[p.id,i+1]))}
function prospectRangeV35(p){const C=college35(),conf=C.scouting[p.id]||0,unc=Math.max(2,Math.ceil((100-conf)/13));return {low:clamp(p.nba_readiness-unc,55,99),high:clamp(p.nba_readiness+unc,55,99),potLow:clamp(p.potential-unc-2,p.nba_readiness,99),potHigh:clamp(p.potential+unc,55,99),confidence:conf}}
function collegeStatLineV35(p){const s=college35()?.stats?.[p.id];if(!s?.gp)return null;return {gp:s.gp,pts:(s.pts/s.gp).toFixed(1),reb:(s.reb/s.gp).toFixed(1),ast:(s.ast/s.gp).toFixed(1),stl:(s.stl/s.gp).toFixed(1),blk:(s.blk/s.gp).toFixed(1)}}
function collegeGameLineV35(p,date,opp){const base=22+(31-p.rank)*.17;const h=collegeHashV35(`${date}|${p.id}|line`),h2=collegeHashV35(`${date}|${p.id}|r`),h3=collegeHashV35(`${date}|${p.id}|a`);const big=p.position.includes('C')||p.position.includes('PF'),guard=p.position.includes('PG');const pts=Math.max(2,Math.round(base+(h-.5)*18));const reb=Math.max(0,Math.round((big?8.0:4.7)+(h2-.5)*7));const ast=Math.max(0,Math.round((guard?6.0:2.6)+(h3-.5)*6));const stl=Math.max(0,Math.round(1+(collegeHashV35(`${date}|${p.id}|s`)-.5)*2));const blk=Math.max(0,Math.round((big?1.5:.5)+(collegeHashV35(`${date}|${p.id}|b`)-.5)*2));const tov=Math.max(0,Math.round(2+(collegeHashV35(`${date}|${p.id}|t`)-.5)*3));return {date,opp,pts,reb,ast,stl,blk,tov}}
function applyCollegeProspectGameV35(programId,oppId,date){const C=college35();for(const p of CD35.prospects||[]){if(p.program_id!==programId)continue;const line=collegeGameLineV35(p,date,oppId),s=C.stats[p.id];s.gp++;for(const k of ['pts','reb','ast','stl','blk','tov'])s[k]+=line[k];s.last.unshift(line);s.last=s.last.slice(0,8);const perf=line.pts+line.reb*.55+line.ast*.7+line.stl*1.5+line.blk*1.5-line.tov*.6,expected=19+(31-p.rank)*.15,delta=clamp((perf-expected)/12,-1.2,1.2);C.stock[p.id]=clamp((C.stock[p.id]||0)+delta,-7,7);C.stockHistory[p.id]=C.stockHistory[p.id]||[];C.stockHistory[p.id].push({date,delta:+delta.toFixed(2),stock:+C.stock[p.id].toFixed(2),line});C.stockHistory[p.id]=C.stockHistory[p.id].slice(-30);if(line.pts>=30||perf>=34){const prog=collegeProgramV35(programId);C.news.unshift({date,type:'performance',prospect:p.id,text:`${p.name} posts ${line.pts} PTS, ${line.reb} REB and ${line.ast} AST for ${prog?.name||p.program}.`});C.news=C.news.slice(0,40)}}}
function simulateCollegeDayV35(date){const C=college35(),y=C.seasonYear,start=`${y}-11-02`,end=`${y+1}-03-15`;if(date<start||date>end)return;const day=new Date(date+'T12:00:00').getDay();if(![2,3,6].includes(day))return;let candidates=(CD35.programs||[]).filter(t=>(C.records[t.id]?.gp||0)<30).sort((a,b)=>(C.records[a.id]?.gp||0)-(C.records[b.id]?.gp||0)||collegeHashV35(`${date}|${a.id}`)-collegeHashV35(`${date}|${b.id}`));const maxTeams=Math.min(candidates.length,24);candidates=candidates.slice(0,maxTeams-(maxTeams%2));for(let i=0;i<candidates.length;i+=2){const home=candidates[i],away=candidates[i+1],hr=C.records[home.id],ar=C.records[away.id];if(hr.gp>=30||ar.gp>=30)continue;const homeEdge=(home.power-away.power)*.35+3.0,noise=(collegeHashV35(`${date}|${home.id}|${away.id}|score`)-.5)*22,margin=homeEdge+noise,base=72+Math.round((home.power+away.power-150)*.15);let homeScore=Math.max(49,Math.round(base+margin/2)),awayScore=Math.max(47,Math.round(base-margin/2));if(homeScore===awayScore)homeScore++;const homeWin=homeScore>awayScore;for(const [r,won,pf,pa] of [[hr,homeWin,homeScore,awayScore],[ar,!homeWin,awayScore,homeScore]]){r.gp++;won?r.w++:r.l++;r.pf+=pf;r.pa+=pa;r.last5.push(won?'W':'L');r.last5=r.last5.slice(-5)}C.results.push({date,home:home.id,away:away.id,homeScore,awayScore,simulated:true});applyCollegeProspectGameV35(home.id,away.id,date);applyCollegeProspectGameV35(away.id,home.id,date)}C.results=C.results.slice(-900)}
function simulateCollegeToV35(target){const C=college35();if(!C)return;let d=C.lastProcessedDate||`${C.seasonYear}-11-01`,guard=0;while(d<target&&guard++<800){d=addDays(d,1);simulateCollegeDayV35(d)}C.lastProcessedDate=d;refreshCollegeScoutingV35()}
function scoutProspectSeasonV35(id){const C=college35(),p=collegeProspectMapV35.get(id);if(!p)return;refreshCollegeScoutingV35();if(C.scoutingCredits<1){toast('NO SCOUTING ASSIGNMENTS LEFT THIS WEEK');return}C.scoutingCredits--;C.scouting[id]=clamp((C.scouting[id]||0)+18,0,100);if(!C.watchlist.includes(id))C.watchlist.push(id);persist();renderView();toast(`${p.name.toUpperCase()} · SCOUTING UPDATED`)}
function scoutGroupV35(group){const C=college35();refreshCollegeScoutingV35();if(C.scoutingCredits<2){toast('NEED 2 SCOUTING ASSIGNMENTS');return}C.scoutingCredits-=2;const match=p=>group==='guards'?/[P|S]G/.test(p.position):group==='wings'?/(SF|SG)/.test(p.position)&&!p.position.includes('PG'):/(PF|C)/.test(p.position);for(const p of CD35.prospects||[])if(match(p))C.scouting[p.id]=clamp((C.scouting[p.id]||0)+8,0,100);persist();renderView();toast(`${group.toUpperCase()} SCOUTING SWEEP COMPLETE`)}
function toggleCollegeWatchV35(id){const C=college35(),i=C.watchlist.indexOf(id);if(i>=0)C.watchlist.splice(i,1);else C.watchlist.push(id);persist();renderView()}
function nbaDraftOrderV35(){const prior=SC.prior_season_records||{};const ranked=teams.map(t=>{const r=record(t.abbr),gp=r.w+r.l,pr=prior[t.abbr]||{w:41,l:41};return {abbr:t.abbr,pct:gp?r.pct:pr.w/(pr.w+pr.l),diff:gp?r.diff:0}}).sort((a,b)=>a.pct-b.pct||a.diff-b.diff);return ranked.map((x,i)=>{const asset=(state.draftAssets||[]).find(a=>a.year===2027&&a.round===1&&a.origin===x.abbr);return {pick:i+1,origin:x.abbr,owner:asset?.owner||x.abbr}})}
function needGroupV35(a){const groups={guard:['PG','SG'],wing:['SG','SF'],big:['PF','C']};const scores=Object.entries(groups).map(([g,pos])=>{const vals=teamPlayers(a,{activeOnly:true}).filter(p=>p.positions?.some(x=>pos.includes(x))).sort((x,y)=>overall(y)-overall(x)).slice(0,3).map(overall);return [g,vals.length?vals.reduce((s,v)=>s+v,0)/vals.length:55]});return scores.sort((x,y)=>x[1]-y[1])[0]?.[0]||'wing'}
function prospectGroupV35(p){if(p.position.includes('C')||p.position.includes('PF'))return'big';if(p.position.includes('PG'))return'guard';return'wing'}
function mockDraftV35(){const board=collegeBoardV35(),available=[...board],order=nbaDraftOrderV35();return order.map(slot=>{const need=needGroupV35(slot.owner),window=available.slice(0,Math.min(6,available.length));let best=window[0];for(const p of window){const bscore=-board.indexOf(p)+(prospectGroupV35(p)===need?1.4:0)+(college35().stock[p.id]||0)*.15;const oscore=-board.indexOf(best)+(prospectGroupV35(best)===need?1.4:0)+(college35().stock[best.id]||0)*.15;if(bscore>oscore)best=p}available.splice(available.indexOf(best),1);return {...slot,prospect:best,need}})}
function collegeProspectCardV35(p,index){const C=college35(),range=prospectRangeV35(p),line=collegeStatLineV35(p),rank=collegeRankMapV35().get(p.id),stock=C.stock[p.id]||0,watched=C.watchlist.includes(p.id);return `<article class="v35ProspectCard"><button class="v35ProspectMain" data-college-prospect="${p.id}"><div class="v35Rank"><b>${rank}</b><small>${stock>.7?'↑':stock<-.7?'↓':'—'}</small></div><div><span>${esc(p.program)} · ${esc(p.class)} · ${esc(p.height)}</span><h3>${esc(p.name)}</h3><p>${esc(p.position)} · ${esc(p.archetype)}</p>${line?`<small>${line.pts} PTS · ${line.reb} REB · ${line.ast} AST · ${line.gp} GP</small>`:`<small>2026–27 SEASON NOT STARTED</small>`}</div><strong>${range.low}–${range.high}<em>NBA OVR</em></strong></button><div class="v35ProspectActions"><button data-college-watch="${p.id}" class="${watched?'active':''}">${watched?'★ WATCHING':'☆ WATCH'}</button><button data-college-scout="${p.id}" ${range.confidence>=100?'disabled':''}>${range.confidence>=100?'FULL REPORT':`SCOUT · ${range.confidence}%`}</button></div></article>`}
