function v37VotingBreakdown(list,scoreFn){if(!list?.length)return[];const raw=list.slice(0,5).map(x=>({id:x.id||x.team,score:scoreFn(x)})),min=Math.min(...raw.map(x=>x.score)),weights=raw.map(x=>Math.max(.5,x.score-min+3)),sum=weights.reduce((a,b)=>a+b,0)||1;let used=0;return raw.map((x,i)=>{let pct=i===raw.length-1?100-used:Math.round(weights[i]/sum*100);used+=pct;return {...x,pct}})}
