 if(state.awards?.generatedFor===state.seasonYear&&state.awards?.all_nba_first)return;const S=seasonEventsV37(),eligible=v37EligibleAwards();
 const mvp=[...eligible].sort((a,b)=>v37AwardScore(b)-v37AwardScore(a))[0],dpoy=[...eligible].sort((a,b)=>defenseAwardScore(b)-defenseAwardScore(a))[0];
