 const roy=[...rookies].sort((a,b)=>v37AwardScore(b)-v37AwardScore(a))[0],smoy=[...bench].sort((a,b)=>v37AwardScore(b)-v37AwardScore(a))[0],mip=[...eligible].filter(p=>p.age<=28).sort((a,b)=>liveMipScore(b)-liveMipScore(a))[0];
 const coach=liveCoachCandidatesV37(1)[0],first=allLeagueTeamsV37(eligible,v37AwardScore,5),second=allLeagueTeamsV37(eligible.filter(p=>!first.includes(p.id)),v37AwardScore,5),def1=allLeagueTeamsV37(eligible,defenseAwardScore,5),rook1=allLeagueTeamsV37(rookies,v37AwardScore,5);
