 state.contractMarket=state.contractMarket||{version:39,agentLinks:{},agentRelations:{},negotiations:{},extensionTalks:{},agreements:[],marketHistory:[],offerSheetHistory:[],signAndTradeTalks:[],lastMarketDay:null};
 const C=state.contractMarket;C.version=39;C.agentLinks=C.agentLinks||{};C.agentRelations=C.agentRelations||{};C.negotiations=C.negotiations||{};C.extensionTalks=C.extensionTalks||{};C.agreements=C.agreements||[];C.marketHistory=C.marketHistory||[];C.offerSheetHistory=C.offerSheetHistory||[];C.signAndTradeTalks=C.signAndTradeTalks||[];return C
