/* v0.40 — INJURIES, FATIGUE + MEDICAL STAFF */
const V40_HEALTH_VERSION=40;
let medicalTabV40='overview';
const V40_MED_FIRST=['Avery','Jordan','Morgan','Cameron','Taylor','Riley','Casey','Parker','Drew','Quinn','Hayden','Reese','Rowan','Emerson','Skyler','Blake','Kendall','Devon','Finley','Sawyer','Alex','Jamie','Sam','Logan','Jesse','Micah','Charlie','Dakota','Robin','Marley'];
const V40_MED_LAST=['Mercer','Santos','Hale','Bennett','Navarro','Kim','Foster','Patel','Rivers','Brooks','Chen','Walsh','Morris','Grant','Ellis','Perry','Diaz','Cole','Reed','Vega','Hayes','Shaw','Bell','Cruz','Flynn','Price','Stone','Lane','West','Rowe'];
const V40_MED_ROLES=[
 {key:'trainer',label:'HEAD ATHLETIC TRAINER',focus:'Return-to-play + prevention'},
 {key:'performance',label:'DIRECTOR OF PERFORMANCE',focus:'Conditioning + workload'},
 {key:'rehab',label:'REHAB SPECIALIST',focus:'Recovery + reconditioning'}
];
const V40_POLICY={
 conservative:{label:'CONSERVATIVE',recovery:.96,risk:.82,return:1.10,desc:'Protect availability. Slower return-to-play, lower recurrence risk.'},
 balanced:{label:'BALANCED',recovery:1,risk:1,return:1,desc:'Balanced workload, recovery and return-to-play decisions.'},
 aggressive:{label:'AGGRESSIVE',recovery:1.06,risk:1.18,return:.91,desc:'Push availability. Faster returns with more recurrence exposure.'}
};
function v40Hash(s){let h=2166136261>>>0;for(const c of String(s)){h^=c.charCodeAt(0);h=Math.imul(h,16777619)}return (h>>>0)/4294967296}
function v40DateDiff(a,b){return Math.round((new Date(b+'T12:00:00')-new Date(a+'T12:00:00'))/86400000)}
function v40MedicalPerson(a,role,index){const ti=Math.max(0,teams.findIndex(t=>t.abbr===a)),seed=v40Hash(`${a}|${role.key}|MED40`),fi=(ti*3+index*7+Math.floor(seed*29))%V40_MED_FIRST.length,li=(ti*11+index*13+Math.floor(seed*31))%V40_MED_LAST.length,name=`${V40_MED_FIRST[fi]} ${V40_MED_LAST[li]}`;const base=66+Math.round(seed*20),ratings={prevention:clamp(base+Math.round((v40Hash(name+'p')-.5)*14),55,94),recovery:clamp(base+Math.round((v40Hash(name+'r')-.5)*14),55,94),rehab:clamp(base+Math.round((v40Hash(name+'h')-.5)*14),55,94),conditioning:clamp(base+Math.round((v40Hash(name+'c')-.5)*14),55,94),return_to_play:clamp(base+Math.round((v40Hash(name+'t')-.5)*14),55,94)};if(role.key==='trainer'){ratings.prevention=clamp(ratings.prevention+5,55,96);ratings.return_to_play=clamp(ratings.return_to_play+6,55,96)}if(role.key==='performance'){ratings.conditioning=clamp(ratings.conditioning+7,55,96);ratings.recovery=clamp(ratings.recovery+3,55,96)}if(role.key==='rehab'){ratings.rehab=clamp(ratings.rehab+8,55,97);ratings.recovery=clamp(ratings.recovery+4,55,96)}return {id:`MED40-${a}-${role.key}`,name,role:role.key,title:role.label,focus:role.focus,ratings,simulated:true}}
function health40(){
 if(!state)return null;const old=state.healthPerformance||{};
 if(old.version!==V40_HEALTH_VERSION){state.healthPerformance={version:V40_HEALTH_VERSION,players:old.players||{},teams:old.teams||{},history:old.history||[],lastProcessedDate:old.lastProcessedDate||state.date||'',medicalNews:old.medicalNews||[]}}
 const H=state.healthPerformance;H.players=H.players||{};H.teams=H.teams||{};H.history=H.history||[];H.medicalNews=H.medicalNews||[];
 for(const t of teams){if(!H.teams[t.abbr]){const staff=V40_MED_ROLES.map((r,i)=>v40MedicalPerson(t.abbr,r,i));H.teams[t.abbr]={policy:'balanced',staff,created:state.date}}else{H.teams[t.abbr].policy=H.teams[t.abbr].policy||'balanced';H.teams[t.abbr].staff=H.teams[t.abbr].staff||V40_MED_ROLES.map((r,i)=>v40MedicalPerson(t.abbr,r,i));}}
 return H
}
function medicalTeamV40(a=userTeam){return health40()?.teams?.[a]||null}
function medicalRatingsV40(a=userTeam){const M=medicalTeamV40(a),s=M?.staff||[];const avg=k=>s.length?Math.round(s.reduce((n,x)=>n+(x.ratings?.[k]||70),0)/s.length):70;return {prevention:avg('prevention'),recovery:avg('recovery'),rehab:avg('rehab'),conditioning:avg('conditioning'),return_to_play:avg('return_to_play')}}
function healthEntryV40(p){const H=health40();if(!p||!H)return null;let e=H.players[p.id];if(!e){e=H.players[p.id]={fatigue:Math.round(v40Hash(`${p.id}|fatigue40`)*8),lastUpdated:state.date,lastGameDate:null,returnStage:null,gamePlan:null,careerInjuries:0,bodyHistory:{},medicalFlags:[]}}e.fatigue=clamp(+e.fatigue||0,0,100);e.bodyHistory=e.bodyHistory||{};return e}
function workloadV40(p,onDate=state.date,windowDays=7){const all=[...(state.gameLogs?.[p.id]||[]),...(state.playoffGameLogs?.[p.id]||[])];let min=0,gamesPlayed=0;for(const g of all){const gap=v40DateDiff(g.date,onDate);if(gap>=0&&gap<windowDays){min+=+g.min||0;gamesPlayed++}}return {minutes:+min.toFixed(1),games:gamesPlayed}}
function fatigueBandV40(v){if(v>=78)return {label:'EXHAUSTED',cls:'critical'};if(v>=62)return {label:'HEAVY LOAD',cls:'high'};if(v>=46)return {label:'TIRED',cls:'elevated'};if(v>=28)return {label:'NORMAL LOAD',cls:'normal'};return {label:'FRESH',cls:'fresh'}}
function returnStageV40(p,onDate=state.date){const e=healthEntryV40(p),r=e?.returnStage;if(!r)return null;if(onDate>r.end_date){e.returnStage=null;return null}return r}
function planV40(p,onDate=state.date){const e=healthEntryV40(p),g=e?.gamePlan;return g&&g.game_date===onDate?g:null}
function minuteCapV40(p,onDate=state.date){const plan=planV40(p,onDate),r=returnStageV40(p,onDate);if(plan?.mode==='rest')return 0;if(plan?.mode==='limit')return +plan.cap||24;if(plan?.mode==='full')return 48;if(r?.cap)return +r.cap;const f=healthEntryV40(p)?.fatigue||0;if(f>=82&&p.age>=32)return 28;if(f>=70&&p.age>=34)return 30;return 48}
function conditionV40(p,onDate=state.date){const e=healthEntryV40(p),i=injuryFor(p,onDate);if(i){const total=Math.max(1,v40DateDiff(i.start_date,i.return_date)),left=Math.max(0,v40DateDiff(onDate,i.return_date)),progress=clamp(1-left/total,0,1);return Math.round(clamp(35+progress*37-e.fatigue*.12,28,76))}const r=returnStageV40(p,onDate),returnPenalty=r?clamp((v40DateDiff(onDate,r.end_date)+1)*1.8,4,14):0;return Math.round(clamp(100-e.fatigue*.62-returnPenalty,42,100))}
function medicalStatusV40(p,onDate=state.date){const i=injuryFor(p,onDate),left=i?Math.max(0,injuryDaysLeft(i,onDate)):0;if(i){if(i.severity==='day_to_day'&&left<=1)return {label:'QUESTIONABLE',detail:i.name,cls:'questionable'};if(['minor','moderate'].includes(i.severity)&&left<=2)return {label:'DOUBTFUL',detail:i.name,cls:'doubtful'};return {label:'OUT',detail:i.name,cls:'out'}}const pl=planV40(p,onDate);if(pl?.mode==='rest')return {label:'OUT · REST',detail:'Load management',cls:'out'};const r=returnStageV40(p,onDate);if(r)return {label:'PROBABLE',detail:`${r.cap} MIN recommendation`,cls:'probable'};const f=healthEntryV40(p)?.fatigue||0;if(f>=74)return {label:'PROBABLE',detail:'Heavy workload',cls:'probable'};return {label:'AVAILABLE',detail:fatigueBandV40(f).label,cls:'available'}}
function v40InjuryMeta(name=''){const n=name.toLowerCase();if(n.includes('ankle'))return {body:'ANKLE',group:'lower_body',key:'ankle'};if(n.includes('knee'))return {body:'KNEE',group:'lower_body',key:'knee'};if(n.includes('hamstring'))return {body:'HAMSTRING',group:'lower_body',key:'hamstring'};if(n.includes('calf'))return {body:'CALF',group:'lower_body',key:'calf'};if(n.includes('foot'))return {body:'FOOT',group:'lower_body',key:'foot'};if(n.includes('back'))return {body:'BACK',group:'core',key:'back'};if(n.includes('wrist'))return {body:'WRIST',group:'upper_body',key:'wrist'};if(n.includes('shoulder'))return {body:'SHOULDER',group:'upper_body',key:'shoulder'};if(n.includes('illness'))return {body:'ILLNESS',group:'illness',key:'illness'};return {body:'GENERAL',group:'general',key:'general'}}
function recurrenceRiskV40(p,meta=null){const e=healthEntryV40(p),m=meta||{key:'general'},prior=+(e?.bodyHistory?.[m.key]||0),r=returnStageV40(p),dept=medicalRatingsV40(currentTeam(p)||p.team),policy=V40_POLICY[medicalTeamV40(currentTeam(p)||p.team)?.policy||'balanced'];let risk=.045+prior*.045+(r?.recurrence_risk||0)*.42;risk*=policy?.risk||1;risk*=clamp(1-(dept.rehab-72)*.004,.84,1.10);return clamp(risk,.025,.38)}
function recoveryDaysV40(p,x,raw){const a=currentTeam(p)||p.team,dept=medicalRatingsV40(a),policy=V40_POLICY[medicalTeamV40(a)?.policy||'balanced'];const skill=x.severity==='major'?(dept.rehab*.65+dept.recovery*.35):(dept.recovery*.65+dept.rehab*.35),staffFactor=clamp(1-(skill-75)*.0035,.88,1.09),policyFactor=policy?.return||1;return Math.max(1,Math.round(raw*staffFactor*policyFactor))}
function returnRecommendationV40(p,i,date){const a=currentTeam(p)||i.team_at_injury,dept=medicalRatingsV40(a),policy=V40_POLICY[medicalTeamV40(a)?.policy||'balanced'];const severity=i.severity,base=severity==='major'?24:severity==='moderate'?26:severity==='minor'?28:32,cap=clamp(Math.round(base+(dept.return_to_play-75)/8+(policy===V40_POLICY.conservative?-2:policy===V40_POLICY.aggressive?2:0)),20,34),days=severity==='major'?7:severity==='moderate'?5:severity==='minor'?3:1,meta=v40InjuryMeta(i.name),rr=clamp((.07+(healthEntryV40(p)?.bodyHistory?.[meta.key]||0)*.04)*(policy?.risk||1)*clamp(1-(dept.return_to_play-75)*.004,.82,1.12),.03,.34);return {status:'restricted',start_date:date,end_date:addDays(date,days),cap,injury_name:i.name,body_area:meta.body,recurrence_risk:+rr.toFixed(3),medical_recommendation:true}}
function v40AddMedicalHistory(type,p,text,date=state.date,extra={}){const H=health40(),row={date,type,player_id:p?.id||null,player_name:p?.name||'',team:p?currentTeam(p)||extra.team||null:extra.team||null,text,...extra};H.history.unshift(row);H.history=H.history.slice(0,500);H.medicalNews.unshift(row);H.medicalNews=H.medicalNews.slice(0,80);return row}

// Injury creation now carries body area, recurrence and medical-department recovery effects.
createInjury=function(p,date,source='game',spec=null){if(!p||injuryFor(p,date))return null;const x=spec||weightedInjury(),raw=Math.round(x.min+rng()*(x.max-x.min)),days=recoveryDaysV40(p,x,raw),tm=currentTeam(p),meta=v40InjuryMeta(x.name),e=healthEntryV40(p),prior=+(e.bodyHistory?.[meta.key]||0);backupRotationForInjury(tm);const i={player_id:p.id,team_at_injury:tm,name:x.name,severity:x.severity,body_area:meta.body,body_group:meta.group,recurrence_key:meta.key,start_date:date,return_date:addDays(date,days+1),days_out:days,base_days_out:raw,source,recurrence_risk:+clamp(.04+prior*.05+(e.fatigue||0)*.0012,.03,.38).toFixed(3),medical_model:'v0.40'};state.injuries=state.injuries||{};state.injuries[p.id]=i;state.injuryHistory=state.injuryHistory||[];state.injuryHistory.unshift({...i,player_name:p.name});if(state.injuryHistory.length>500)state.injuryHistory.length=500;e.careerInjuries=(e.careerInjuries||0)+1;e.bodyHistory[meta.key]=prior+1;e.returnStage=null;e.gamePlan=null;v40AddMedicalHistory('INJURY',p,`${p.name}: ${x.name} · ${days} day estimate.`,date,{body_area:meta.body,severity:x.severity});addTransaction('MEDICAL',`${p.name} is out with ${x.name.toLowerCase()} (${days} day${days===1?'':'s'}).`,date);if(tm)ensureRotation(tm,true);return i};

const v40InjuryRiskBase=injuryRisk;
injuryRisk=function(p,minutes=28){const base=v40InjuryRiskBase(p,minutes),e=healthEntryV40(p),f=+e?.fatigue||0,metaRisk=recurrenceRiskV40(p),a=currentTeam(p)||p.team,dept=medicalRatingsV40(a),policy=V40_POLICY[medicalTeamV40(a)?.policy||'balanced'],fatigueFactor=1+Math.max(0,f-18)*.0085,historyFactor=1+Math.max(0,metaRisk-.045)*1.15,prevention=clamp(1-(dept.prevention-75)*.0032,.88,1.08);return clamp(base*fatigueFactor*historyFactor*prevention*(policy?.risk||1),.0012,.042)};

const v40IsAvailableBase=isAvailable;
isAvailable=function(p,onDate=state.date){if(!v40IsAvailableBase(p,onDate))return false;const pl=planV40(p,onDate);return pl?.mode!=='rest'};
availabilityLabel=function(p,onDate=state.date){const m=medicalStatusV40(p,onDate),c=conditionV40(p,onDate);return `${m.label} · ${c}% CONDITION`};

// Return-to-play is staged instead of snapping from OUT to unrestricted.
processMedicalDay=function(date){const H=health40();state.injuries=state.injuries||{};const affected=new Set();if(H.lastProcessedDate!==date){for(const p of players){if(!currentTeam(p)||!['active','two_way'].includes(currentStatus(p)))continue;const e=healthEntryV40(p),a=currentTeam(p),dept=medicalRatingsV40(a),inj=state.injuries[p.id];const base=inj?5.5:11.5,staff=(dept.recovery-70)*.13,stam=(rating(p,'stamina')-70)*.045,rest=planV40(p,date)?.mode==='rest'?7:0;e.fatigue=clamp(e.fatigue-(base+staff+stam+rest),0,100);e.lastUpdated=date;if(e.gamePlan&&e.gamePlan.game_date<date)e.gamePlan=null;const r=e.returnStage;if(r&&date>r.end_date){e.returnStage=null;v40AddMedicalHistory('FULL CLEARANCE',p,`${p.name} completed return-to-play restrictions.`,date,{body_area:r.body_area})}}
 H.lastProcessedDate=date}
 for(const [id,i] of Object.entries(state.injuries)){if(date>=i.return_date){const p=byId.get(id),tm=currentTeam(p)||i.team_at_injury;delete state.injuries[id];affected.add(tm);if(p){const e=healthEntryV40(p),r=returnRecommendationV40(p,i,date);e.returnStage=r;e.fatigue=clamp(e.fatigue+8,0,100);v40AddMedicalHistory('CLEARED',p,`${p.name} medically cleared with a ${r.cap}-minute return recommendation.`,date,{body_area:i.body_area,cap:r.cap,recurrence_risk:r.recurrence_risk});addTransaction('CLEARED',`${p.name} has been cleared to return on a ${r.cap}-minute recommendation.`,date)}}}
 for(const tm of affected){if(!tm)continue;const still=activeTeamInjuries(tm,date);if(!still.length&&state.injuryRotationBackups?.[tm]){const old=state.injuryRotationBackups[tm];delete state.injuryRotationBackups[tm];if(rotationValid(tm,old))state.rotations[tm]=old;else ensureRotation(tm,true)}else ensureRotation(tm,true)}
 ensureCbaLongTailState();processWaiverWire(date);state.disabledPlayerExceptions=state.disabledPlayerExceptions.filter(x=>!x.expires||date<x.expires||x.used);pruneTransactionLocks();pruneTradeExceptions();
};

function v40RecentGameDates(p,onDate=state.date){return [...(state.gameLogs?.[p.id]||[]),...(state.playoffGameLogs?.[p.id]||[])].filter(g=>g.date<=onDate).sort((a,b)=>b.date.localeCompare(a.date)).slice(0,4).map(g=>g.date)}
function applyGameLoadV40(result,date,home,away){if(!result?.box)return;for(const [side,a] of [['home',home],['away',away]]){const played=new Set();for(const line of result.box?.[side]||[]){const p=byId.get(line.player_id);if(!p||!line.min)continue;played.add(p.id);const e=healthEntryV40(p),prior=e.lastGameDate,stam=clamp(1+(78-rating(p,'stamina'))*.006,.88,1.16),b2b=prior&&v40DateDiff(prior,date)<=1?1.18:1,load=(+line.min||0)*.85*stam*b2b;e.fatigue=clamp(e.fatigue+load,0,100);e.lastGameDate=date;e.lastMinutes=+line.min||0;e.lastUpdated=date;if(e.gamePlan?.game_date===date)e.gamePlan=null}
 for(const p of teamPlayers(a,{activeOnly:true})){if(played.has(p.id))continue;const e=healthEntryV40(p),pl=planV40(p,date);if(pl?.mode==='rest'){e.fatigue=clamp(e.fatigue-10,0,100);e.gamePlan=null;v40AddMedicalHistory('LOAD MANAGEMENT',p,`${p.name} rested against ${a===home?away:home}.`,date,{team:a})}}}}
const v40SimGameBase=simulateGame;
simulateGame=function(g){if(state.results[g.id])return;prepareHealthPlansV40(g.home,g.date);prepareHealthPlansV40(g.away,g.date);v40SimGameBase(g);const r=state.results[g.id];if(r&&!r.health_v40){applyGameLoadV40(r,g.date,g.home,g.away);r.health_v40=true}};

function prepareHealthPlansV40(a,date){for(const p of teamPlayers(a,{activeOnly:true})){const e=healthEntryV40(p);if(a===userTeam)continue;if(e.gamePlan?.game_date===date)continue;const r=returnStageV40(p,date),f=e.fatigue;if(r)e.gamePlan={mode:'limit',cap:r.cap,game_date:date,source:'medical'};else if(f>=82&&p.age>=31)e.gamePlan={mode:'rest',cap:0,game_date:date,source:'cpu_load'};else if(f>=68)e.gamePlan={mode:'limit',cap:p.age>=31?28:30,game_date:date,source:'cpu_load'}}}
const v40AllocateMinutesBase=allocateMinutes;
allocateMinutes=function(ps,a){let arr=v40AllocateMinutesBase(ps,a).map(x=>+x||0),caps=ps.map(p=>minuteCapV40(p,state.date)),excess=0;for(let i=0;i<arr.length;i++){if(arr[i]>caps[i]){excess+=arr[i]-caps[i];arr[i]=caps[i]}}let guard=0;while(excess>.01&&guard++<1000){let best=-1,room=0;for(let i=0;i<arr.length;i++){const r=caps[i]-arr[i];if(r>room+.001){room=r;best=i}}if(best<0||room<=0)break;const add=Math.min(room,excess,1);arr[best]+=add;excess-=add}return arr};
const v40MetricsBase=metrics;
metrics=function(a){const m=v40MetricsBase(a),rows=rotationPlayers(a),ws=rows.reduce((s,x)=>s+x.min,0)||1,avg=rows.reduce((s,x)=>s+(healthEntryV40(x.p)?.fatigue||0)*x.min,0)/ws,pen=clamp((avg-34)*.035,0,1.55),dept=medicalRatingsV40(a),conditioning=clamp((dept.conditioning-75)*.012,-.18,.24),net=Math.max(0,pen-conditioning);return {...m,off:m.off-net,def:m.def-net*.78,ov:m.ov-net,healthPenalty:+net.toFixed(2),avgFatigue:+avg.toFixed(1)}};

// Daily activities now have real physical consequences.
ACTIONS.practice.note='Full-team work. +1 rotation morale; moderate physical load.';
ACTIONS.shooting.note='Low-load shooting reps. Small fatigue cost; shooting development credit.';
ACTIONS.defense.note='Scheme + coverage work. Moderate fatigue cost; defensive development credit.';
ACTIONS.recovery.note='Recovery treatment and reduced load. Meaningfully lowers fatigue today.';
ACTIONS.film.note='Film/scouting work with almost no physical load.';
ACTIONS.development.note='Extra development workload for the best U24 players.';
const v40ApplyDailyActionBase=applyDailyAction;
applyDailyAction=function(id){const before=activeDailyAction?.();if(before)return v40ApplyDailyActionBase(id);v40ApplyDailyActionBase(id);const roster=teamPlayers(userTeam,{activeOnly:true}).sort((a,b)=>overall(b)-overall(a)),delta={practice:8,shooting:3,defense:6,recovery:-18,film:1,development:0}[id]||0;for(const p of roster){const e=healthEntryV40(p);let d=delta;if(id==='development')d=p.age<=23?7:1;e.fatigue=clamp(e.fatigue+d,0,100);e.lastUpdated=state.date}v40AddMedicalHistory('TRAINING',null,`${team(userTeam)?.abbr||userTeam}: ${ACTIONS[id]?.label||id}.`,state.date,{team:userTeam,activity:id});persist()};

function nextTeamGameV40(a=userTeam){return seasonGamesFor(a).find(g=>!resultFor(g)&&g.date>=state.date)||null}
function setLoadPlanV40(id,mode,cap=null){const p=byId.get(id);if(!p||currentTeam(p)!==userTeam)return;const g=userGameToday()||nextTeamGameV40(userTeam);if(!g){toast('NO UPCOMING GAME');return}const e=healthEntryV40(p),r=returnStageV40(p,g.date);if(mode==='full'&&r){e.gamePlan={mode:'full',cap:48,game_date:g.date,source:'gm_override',override_medical:true};v40AddMedicalHistory('MEDICAL OVERRIDE',p,`${p.name} cleared for full workload by GM override despite ${r.cap}-minute recommendation.`,state.date,{risk:'elevated'})}else e.gamePlan={mode,cap:mode==='limit'?(+cap||24):mode==='rest'?0:48,game_date:g.date,source:'gm'};persist();renderView();toast(mode==='rest'?'REST PLAN SET':mode==='limit'?`${e.gamePlan.cap}-MINUTE LIMIT SET`:'FULL GO SET')}
function setMedicalPolicyV40(a,key){if(!V40_POLICY[key])return;medicalTeamV40(a).policy=key;v40AddMedicalHistory('POLICY',null,`${a} medical policy set to ${V40_POLICY[key].label}.`,state.date,{team:a,policy:key});persist();renderView();toast(`MEDICAL POLICY · ${V40_POLICY[key].label}`)}
function teamHealthSummaryV40(a=userTeam){const roster=teamPlayers(a,{activeOnly:true}),fat=roster.map(p=>healthEntryV40(p)?.fatigue||0),avg=fat.length?Math.round(fat.reduce((s,x)=>s+x,0)/fat.length):0,inj=activeTeamInjuries(a).length,restricted=roster.filter(p=>returnStageV40(p)).length,heavy=roster.filter(p=>(healthEntryV40(p)?.fatigue||0)>=62).length;return {avg,condition:Math.round(clamp(100-avg*.62,40,100)),inj,restricted,heavy}}
function medicalPortalV40(a=userTeam){const s=teamHealthSummaryV40(a),M=medicalTeamV40(a),r=medicalRatingsV40(a);return `<section class="v40MedicalPortal"><div><span>HEALTH + PERFORMANCE</span><b>${s.condition}% TEAM CONDITION · ${s.inj} OUT</b><small>${V40_POLICY[M?.policy||'balanced'].label} policy · Recovery ${r.recovery} · Prevention ${r.prevention}${s.heavy?` · ${s.heavy} heavy-load`:''}</small></div><button data-jump="medical">MEDICAL CENTER</button></section>`}
function medicalPlayerRowV40(p){const e=healthEntryV40(p),m=medicalStatusV40(p),f=fatigueBandV40(e.fatigue),w=workloadV40(p),r=returnStageV40(p),g=userGameToday()||nextTeamGameV40(userTeam),pl=g?planV40(p,g.date):null,rr=Math.round(recurrenceRiskV40(p)*100);return `<article class="v40HealthRow ${m.cls}">${img(p)}<button class="v40HealthName" data-player="${p.id}"><span>${m.label}</span><b>${esc(p.name)}</b><small>${conditionV40(p)}% condition · ${f.label} · ${w.minutes} MIN / 7D</small></button><div class="v40HealthNums"><b>${Math.round(e.fatigue)}</b><span>FATIGUE</span><small>${rr}% REINJURY</small></div><div class="v40LoadActions"><button data-health-plan="rest" data-health-player="${p.id}" class="${pl?.mode==='rest'?'active':''}">REST</button><button data-health-plan="limit" data-health-cap="24" data-health-player="${p.id}" class="${pl?.mode==='limit'&&pl.cap===24?'active':''}">24 MIN</button><button data-health-plan="limit" data-health-cap="28" data-health-player="${p.id}" class="${pl?.mode==='limit'&&pl.cap===28?'active':''}">28 MIN</button><button data-health-plan="full" data-health-player="${p.id}" class="${pl?.mode==='full'?'active':''}">FULL GO</button></div>${r?`<div class="v40ReturnBand"><b>RETURN-TO-PLAY</b><span>${r.cap} MIN recommended through ${shortDate(r.end_date)} · ${Math.round(r.recurrence_risk*100)}% modeled recurrence risk</span></div>`:''}</article>`}
function medicalDepartmentV40(a=userTeam){const M=medicalTeamV40(a),r=medicalRatingsV40(a);return `<section class="v40Department"><div class="sectionHead"><h2>Medical + Performance Department</h2><span>SIMULATED STAFF</span></div><div class="v40MedStaff">${(M.staff||[]).map(s=>`<article><i>${initials(s.name)}</i><div><span>${s.title}</span><b>${esc(s.name)}</b><small>${s.focus}</small></div><strong>${Math.round(Object.values(s.ratings).reduce((x,y)=>x+y,0)/5)}</strong></article>`).join('')}</div><div class="v40MedRatings">${Object.entries(r).map(([k,v])=>`<div><span>${pretty(k)}</span><b>${v}</b><i><em style="width:${v}%"></em></i></div>`).join('')}</div><p class="v40SimNote">Medical staff identities, ratings and recommendations are fictional NBA Courtside simulation data — not claims about real team medical personnel or real medical advice.</p></section>`}
function medicalPolicyV40(a=userTeam){const M=medicalTeamV40(a);return `<section class="v40Policy"><div class="sectionHead"><h2>Return-to-Play Policy</h2><span>${V40_POLICY[M.policy].label}</span></div><div>${Object.entries(V40_POLICY).map(([k,v])=>`<button data-med-policy="${k}" class="${M.policy===k?'active':''}"><b>${v.label}</b><span>${v.desc}</span></button>`).join('')}</div></section>`}
function medicalHistoryV40(){const H=health40(),rows=H.history.filter(x=>!x.team||x.team===userTeam||x.player_id&&byId.get(x.player_id)&&currentTeam(byId.get(x.player_id))===userTeam).slice(0,60);return `<section class="v40History"><div class="sectionHead"><h2>Medical History</h2><span>${rows.length} EVENTS</span></div>${rows.length?rows.map(x=>`<article><span>${shortDate(x.date)}</span><div><b>${esc(x.type)}</b><small>${esc(x.text)}</small></div></article>`).join(''):'<div class="notice">No medical events recorded in this franchise yet.</div>'}</section>`}
function medicalViewV40(){const roster=teamPlayers(userTeam,{activeOnly:true}).sort((a,b)=>{const ai=injuryFor(a)?1:0,bi=injuryFor(b)?1:0;return bi-ai||(healthEntryV40(b)?.fatigue||0)-(healthEntryV40(a)?.fatigue||0)||overall(b)-overall(a)}),s=teamHealthSummaryV40(userTeam),M=medicalTeamV40(userTeam);return `<div class="v40MedicalPage"><section class="v40MedicalHero"><div><span>NBA COURTSIDE · HEALTH + PERFORMANCE</span><h1>AVAILABILITY<br>MATTERS.</h1><p>Workload, fatigue, injury history, rehab and return-to-play decisions persist across the season.</p></div><div><b>${s.condition}%</b><small>TEAM CONDITION</small><strong>${s.inj} OUT · ${s.restricted} RESTRICTED</strong></div></section><div class="v40MedTabs"><button data-med-tab="overview" class="${medicalTabV40==='overview'?'active':''}">ROSTER HEALTH</button><button data-med-tab="staff" class="${medicalTabV40==='staff'?'active':''}">MEDICAL STAFF</button><button data-med-tab="history" class="${medicalTabV40==='history'?'active':''}">HISTORY</button></div>${medicalTabV40==='staff'?medicalDepartmentV40()+medicalPolicyV40():medicalTabV40==='history'?medicalHistoryV40():`<section class="v40Availability"><div class="sectionHead"><h2>Roster Health</h2><span>${V40_POLICY[M.policy].label} POLICY</span></div><div class="v40HealthList">${roster.map(medicalPlayerRowV40).join('')}</div></section>${medicalPolicyV40()}`}</div>`}
function healthProfileV40(p){if(!currentTeam(p)||!['active','two_way'].includes(currentStatus(p)))return'';const e=healthEntryV40(p),m=medicalStatusV40(p),w=workloadV40(p),r=returnStageV40(p),rr=Math.round(recurrenceRiskV40(p)*100);return `<section class="profileCard v40ProfileHealth"><div class="v40ProfileHead"><div><span>HEALTH + PERFORMANCE</span><h3>${m.label}</h3><small>${esc(m.detail)}</small></div><b>${conditionV40(p)}<small>% CONDITION</small></b></div><div class="v40ProfileStats"><div><span>FATIGUE</span><b>${Math.round(e.fatigue)}</b></div><div><span>7-DAY LOAD</span><b>${w.minutes}</b><small>${w.games} GAME${w.games===1?'':'S'}</small></div><div><span>REINJURY</span><b>${rr}%</b></div><div><span>MEDICAL CAP</span><b>${r?r.cap+' MIN':'NONE'}</b></div></div>${injuryFor(p)?`<div class="v40InjuryDetail"><b>${injuryFor(p).body_area||v40InjuryMeta(injuryFor(p).name).body} · ${injuryFor(p).name}</b><span>Estimated return ${shortDate(injuryFor(p).return_date)}</span></div>`:''}</section>`}

