leagueInjuriesView=function(){const rows=players.map(p=>({p,i:injuryFor(p),e:currentTeam(p)?healthEntryV40(p):null,m:currentTeam(p)?medicalStatusV40(p):null})).filter(x=>currentTeam(x.p)&&(x.i||x.e?.returnStage)).sort((a,b)=>(b.i?100:0)+(b.e?.fatigue||0)-((a.i?100:0)+(a.e?.fatigue||0)));return `<section class="v40LeagueMedical"><div class="sectionHead"><h2>League Availability</h2><span>${rows.filter(x=>x.i).length} OUT · ${rows.filter(x=>x.e?.returnStage).length} RETURNING</span></div>${rows.length?`<div class="v40MiniMedical">${rows.map(x=>`<button data-player="${x.p.id}">${img(x.p)}<div><span>${x.m.label} · ${currentTeam(x.p)}</span><b>${esc(x.p.name)}</b><small>${x.i?`${x.i.body_area||''} · ${x.i.name} · ${Math.max(1,injuryDaysLeft(x.i))}D`:`${x.e.returnStage.cap} MIN return plan`}</small></div><strong>${conditionV40(x.p)}%</strong></button>`).join('')}</div>`:'<div class="medicalClear big"><b>NO ACTIVE MEDICAL CASES.</b><span>The league report is clear.</span></div>'}</section>`};

