/* v0.44 — Trade Deadline + Transaction Presentation Expansion */
const V44='0.44';
function deadline44(){
 if(!state||!userTeam)return null;
 const old=state.tradeDeadlineV44||{};
 if(old.version!==44||old.seasonYear!==state.seasonYear){
  state.tradeDeadlineV44={version:44,seasonYear:state.seasonYear,window:state.date===DATES.trade_deadline?0:null,windowHistory:old.seasonYear===state.seasonYear?(old.windowHistory||[]):[],activity:old.seasonYear===state.seasonYear?(old.activity||[]):[],negotiations:old.seasonYear===state.seasonYear?(old.negotiations||{}):{},completedUserTrades:old.seasonYear===state.seasonYear?(old.completedUserTrades||[]):[],marketMoments:old.seasonYear===state.seasonYear?(old.marketMoments||[]):[],closed:state.date>DATES.trade_deadline,closedAt:state.date>DATES.trade_deadline?DATES.trade_deadline:null,recapAcknowledged:false};
 }
 const T=state.tradeDeadlineV44;T.windowHistory=T.windowHistory||[];T.activity=T.activity||[];T.negotiations=T.negotiations||{};T.completedUserTrades=T.completedUserTrades||[];T.marketMoments=T.marketMoments||[];
 if(state.date===DATES.trade_deadline&&T.window==null)T.window=0;
 if(state.date>DATES.trade_deadline){T.closed=true;T.closedAt=T.closedAt||DATES.trade_deadline}
 return T;
}
function deadlineDays44(){if(!state?.seasonStarted)return null;return state.date<=DATES.trade_deadline?daysBetween(state.date,DATES.trade_deadline):-daysBetween(DATES.trade_deadline,state.date)}
function deadlineHeat44(){const d=deadlineDays44();if(d==null||d<0)return 0;if(d===0)return 100;if(d<=2)return 92;if(d<=7)return 78;if(d<=14)return 61;if(d<=30)return 42;return 18}
const DEADLINE_WINDOWS44=['MORNING CALLS','MIDDAY MARKET','FINAL CALLS','CLOSING BELL'];
