function tradeStance44(a){const d=teamDirection(a),r=record(a),gp=r.w+r.l,pay=capHit(a),fo=frontOfficeProfile(a);let id='stand',label='STANDING PAT',note='Open to value, but not forcing a major roster change.';if(['contender','playoff_push'].includes(d.id)){id='buyer';label='BUYER';note='Actively seeking a rotation or top-end upgrade for the current window.'}else if(['rebuild','development'].includes(d.id)){id='seller';label='SELLER';note='Prioritizing youth, picks and future flexibility over marginal short-term wins.'}else if(d.id==='retool'){id='retool';label='RE-TOOLING';note='Willing to move veterans or money if the return improves the age curve and optionality.'}else if(gp>=20&&r.pct<.43){id='seller';label='SELLER';note='Results have pushed the front office toward future value.'}else if(gp>=20&&r.pct>.56){id='buyer';label='BUYER';note='The standings support an aggressive search for playoff help.'}else if(pay>CAP.first_apron&&fo.capDiscipline>.72){id='retool';label='RE-TOOLING';note='Financial pressure makes salary efficiency part of every trade discussion.'}return {id,label,note}}
